        return pos


class Quantifier(Regex):
    def __init__(self, atom, min_count, max_count):
        self.atom = atom
        self.min_count = min_count
        self.max_count = max_count

    def match(self, text, pos):
        """Greedy matching with backtracking."""
        # Collect all possible match positions
        positions = [pos]  # Start with no match
        current_pos = pos

        # Greedily match as many times as possible
        while self.max_count is None or len(positions) - 1 < self.max_count:
            next_pos = self.atom.match(text, current_pos)
            if next_pos == -1:
                break
            positions.append(next_pos)
            current_pos = next_pos

        # Try from the maximum number of matches down to minimum
        for i in range(len(positions) - 1, -1, -1):
            if i >= self.min_count:
                return positions[i]

        return -1


