                'type': 'dict',
                'value': {key: serialize(val) for key, val in o.items()}
            }
        else:
            raise ValueError(f"Unsupported type: {type(o).__name__}")

        objects[placeholder_index] = serialized
        return {'type': 'ref', 'index': placeholder_index}

