            elif obj_type_inner == 'dict':
                if 'value' not in obj_def:
                    raise ValueError(f"Invalid dict data at index {index}: missing 'value'")
                result = {}
                cache[index] = result
                for key, val_data in obj_def['value'].items():
                    if not isinstance(key, str):
