                    result[key] = deserialize(val_data)
            else:
                raise ValueError(f"Invalid object type in objects array: {obj_type_inner}")

            in_progress.discard(index)
            return cache[index]
        else:
            raise ValueError(f"Unknown type: {obj_type}")

