def brainfuck(code: str, input_str: str = "") -> str:
    # Precompute bracket matches
    stack = []
    matches = {}
    for i, c in enumerate(code):
        if c == "[":
            stack.append(i)
        elif c == "]":
            if not stack:
                raise ValueError("Unmatched closing bracket")
            j = stack.pop()
            matches[i] = j
            matches[j] = i
    if stack:
        # there are unmatched opening brackets
        raise ValueError("Unmatched opening bracket")

    tape = [0] * 30000
    ptr = 0
    pc = 0
    output_chars = []
    inp_idx = 0
    n = len(code)

    while pc < n:
        cmd = code[pc]
        if cmd == ">":
            ptr += 1
            if ptr >= len(tape) or ptr < 0:
                raise IndexError("Pointer moved out of tape bounds")
            pc += 1
        elif cmd == "<":
            ptr -= 1
            if ptr < 0 or ptr >= len(tape):
                raise IndexError("Pointer moved out of tape bounds")
            pc += 1
        elif cmd == "+":
            tape[ptr] += 1
            pc += 1
        elif cmd == "-":
            tape[ptr] -= 1
            pc += 1
        elif cmd == ".":
            output_chars.append(chr(tape[ptr]))
            pc += 1
        elif cmd == ",":
            if inp_idx < len(input_str):
                tape[ptr] = ord(input_str[inp_idx])
                inp_idx += 1
            else:
                tape[ptr] = 0
            pc += 1
        elif cmd == "[":
            if tape[ptr] == 0:
                # jump to after matching ]
                pc = matches[pc] + 1
            else:
                pc += 1
        elif cmd == "]":
            if tape[ptr] != 0:
                # jump back to just after matching [
                pc = matches[pc] + 1
            else:
                pc += 1
        else:
            # ignore any other character
            pc += 1

    return "".join(output_chars)

def parse_json(text: str) -> object:
    """
    Strict JSON parser for a single value. Raises ValueError on invalid input.
    """
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def skip_ws(self):
            while self.i < self.n and self.s[self.i] in " \t\n\r":
                self.i += 1

        def peek(self):
            return self.s[self.i] if self.i < self.n else None

        def advance(self):
            ch = self.peek()
            if ch is None:
                raise ValueError("Unexpected end of input")
            self.i += 1
            return ch

        def expect_char(self, ch):
            if self.peek() != ch:
                raise ValueError(f"Expected '{ch}' at position {self.i}")
            self.i += 1

        def parse_value(self):
            self.skip_ws()
            ch = self.peek()
            if ch is None:
                raise ValueError("Empty input or unexpected end")
            if ch == '{':
                return self.parse_object()
            if ch == '[':
                return self.parse_array()
            if ch == '"':
                return self.parse_string()
            if ch == 'n' or ch == 't' or ch == 'f':
                return self.parse_literal()
            # number can start with '-' or digit
            if ch == '-' or ch.isdigit():
                return self.parse_number()
            raise ValueError(f"Invalid value at position {self.i}")

        def parse_object(self):
            # assumes current char is '{'
            self.expect_char('{')
            obj = {}
            self.skip_ws()
            if self.peek() == '}':
                self.i += 1
                return obj
            while True:
                self.skip_ws()
                if self.peek() != '"':
                    raise ValueError(f"Object keys must be strings at position {self.i}")
                key = self.parse_string()
                self.skip_ws()
                if self.peek() != ':':
                    raise ValueError(f"Expected ':' after key at position {self.i}")
                self.i += 1
                val = self.parse_value()
                obj[key] = val
                self.skip_ws()
                ch = self.peek()
                if ch == ',':
                    # detect trailing comma by ensuring next non-ws is not '}'
                    self.i += 1
                    self.skip_ws()
                    if self.peek() == '}' or self.peek() is None:
                        raise ValueError("Trailing comma in object")
                    continue
                if ch == '}':
                    self.i += 1
                    break
                raise ValueError(f"Expected ',' or '}}' in object at position {self.i}")
            return obj

        def parse_array(self):
            # assumes current char is '['
            self.expect_char('[')
            arr = []
            self.skip_ws()
            if self.peek() == ']':
                self.i += 1
                return arr
            while True:
                val = self.parse_value()
                arr.append(val)
                self.skip_ws()
                ch = self.peek()
                if ch == ',':
                    self.i += 1
                    self.skip_ws()
                    if self.peek() == ']' or self.peek() is None:
                        raise ValueError("Trailing comma in array")
                    continue
                if ch == ']':
                    self.i += 1
                    break
                raise ValueError(f"Expected ',' or ']' in array at position {self.i}")
            return arr

        def parse_string(self):
            # assumes current char is '"'
            self.expect_char('"')
            parts = []
            s = self.s
            while True:
                if self.i >= self.n:
                    raise ValueError("Unterminated string")
                ch = s[self.i]
                if ch == '"':
                    self.i += 1
                    return ''.join(parts)
                if ch == '\\':
                    # escape
                    self.i += 1
                    if self.i >= self.n:
                        raise ValueError("Unterminated escape")
                    esc = s[self.i]
                    self.i += 1
                    if esc == '"':
                        parts.append('"')
                    elif esc == '\\':
                        parts.append('\\')
                    elif esc == '/':
                        parts.append('/')
                    elif esc == 'b':
                        parts.append('\b')
                    elif esc == 'f':
                        parts.append('\f')
                    elif esc == 'n':
                        parts.append('\n')
                    elif esc == 'r':
                        parts.append('\r')
                    elif esc == 't':
                        parts.append('\t')
                    elif esc == 'u':
                        # expect 4 hex digits
                        if self.i + 4 > self.n:
                            raise ValueError("Invalid \\u escape (too short)")
                        hex4 = s[self.i:self.i+4]
                        for c in hex4:
                            if c not in '0123456789abcdefABCDEF':
                                raise ValueError("Invalid \\u escape (bad hex)")
                        code = int(hex4, 16)
                        self.i += 4
                        # handle surrogate pairs
                        if 0xD800 <= code <= 0xDBFF:
                            # must be followed by another \uXXXX low surrogate
                            if self.i + 6 <= self.n and s[self.i] == '\\' and s[self.i+1] == 'u':
                                low_hex = s[self.i+2:self.i+6]
                                valid_low = True
                                for c in low_hex:
                                    if c not in '0123456789abcdefABCDEF':
                                        valid_low = False
                                        break
                                if valid_low:
                                    low = int(low_hex, 16)
                                    if 0xDC00 <= low <= 0xDFFF:
                                        # consume low surrogate
                                        self.i += 6
                                        codepoint = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                                        parts.append(chr(codepoint))
                                        continue
                            # invalid surrogate pair
                            raise ValueError("Invalid \\u surrogate pair")
                        else:
                            parts.append(chr(code))
                    else:
                        raise ValueError(f"Invalid escape '\\{esc}'")
                else:
                    # raw character
                    # control characters not allowed
                    if ord(ch) < 0x20:
                        raise ValueError("Invalid control character in string")
                    parts.append(ch)
                    self.i += 1

        def parse_number(self):
            s = self.s
            start = self.i
            # optional minus
            if self.peek() == '-':
                self.i += 1
            # integer part
            if self.i >= self.n:
                raise ValueError("Invalid number")
            if s[self.i] == '0':
                self.i += 1
                # leading zero must not be followed by digit
                if self.i < self.n and s[self.i].isdigit():
                    raise ValueError("Leading zeros are not allowed")
            else:
                if not s[self.i].isdigit():
                    raise ValueError("Invalid number")
                while self.i < self.n and s[self.i].isdigit():
                    self.i += 1
            is_float = False
            # fraction
            if self.i < self.n and s[self.i] == '.':
                is_float = True
                self.i += 1
                if self.i >= self.n or not s[self.i].isdigit():
                    raise ValueError("Invalid fractional part")
                while self.i < self.n and s[self.i].isdigit():
                    self.i += 1
            # exponent
            if self.i < self.n and (s[self.i] == 'e' or s[self.i] == 'E'):
                is_float = True
                self.i += 1
                if self.i < self.n and (s[self.i] == '+' or s[self.i] == '-'):
                    # plus sign allowed in exponent
                    self.i += 1
                if self.i >= self.n or not s[self.i].isdigit():
                    raise ValueError("Invalid exponent")
                while self.i < self.n and s[self.i].isdigit():
                    self.i += 1
            num_text = s[start:self.i]
            try:
                if is_float:
                    return float(num_text)
                else:
                    return int(num_text)
            except Exception:
                raise ValueError("Invalid number conversion")

        def parse_literal(self):
            # null, true, false
            s = self.s
            if s.startswith('null', self.i):
                end = self.i + 4
                if end < self.n and (s[end].isalpha() or s[end].isdigit() or s[end] == '_'):
                    raise ValueError("Invalid token")
                self.i = end
                return None
            if s.startswith('true', self.i):
                end = self.i + 4
                if end < self.n and (s[end].isalpha() or s[end].isdigit() or s[end] == '_'):
                    raise ValueError("Invalid token")
                self.i = end
                return True
            if s.startswith('false', self.i):
                end = self.i + 5
                if end < self.n and (s[end].isalpha() or s[end].isdigit() or s[end] == '_'):
                    raise ValueError("Invalid token")
                self.i = end
                return False
            raise ValueError(f"Invalid literal at position {self.i}")

    p = Parser(text)
    p.skip_ws()
    if p.i >= p.n:
        raise ValueError("Empty input")
    val = p.parse_value()
    p.skip_ws()
    if p.i != p.n:
        raise ValueError("Trailing data")
    return val

import re


def full_match(pattern: str, text: str) -> bool:
    """Return True iff the entire text matches the given pattern.

    Convert re.error into ValueError for malformed patterns.
    """
    try:
        prog = re.compile(pattern)
    except re.error as e:
        raise ValueError(str(e))
    return prog.fullmatch(text) is not None

import json
from typing import Any


def encode(obj: object) -> str:
    """Serialize object graph to a JSON string preserving shared references and cycles.

    Format:
    {
      "root": uid_str,
      "nodes": { uid_str: {"t": type_tag, "v": value_or_refs } }
    }

    type_tag: one of "int","float","bool","null","str","list","dict"
    For list: v is list of uid_str
    For dict: v is mapping from string key to uid_str
    For primitives: v is the primitive value (JSON-serializable)
    """
    obj_to_uid = {}
    nodes = {}
    next_uid = 0

    def new_uid():
        nonlocal next_uid
        uid = str(next_uid)
        next_uid += 1
        return uid

    def add(o: Any) -> str:
        oid = id(o)
        if oid in obj_to_uid:
            return obj_to_uid[oid]
        # assign uid early to allow cycles
        uid = new_uid()
        obj_to_uid[oid] = uid

        # Determine type
        if o is None:
            nodes[uid] = {"t": "null", "v": None}
        elif isinstance(o, bool):
            # bool is subclass of int so check before int
            nodes[uid] = {"t": "bool", "v": o}
        elif isinstance(o, int):
            nodes[uid] = {"t": "int", "v": o}
        elif isinstance(o, float):
            nodes[uid] = {"t": "float", "v": o}
        elif isinstance(o, str):
            nodes[uid] = {"t": "str", "v": o}
        elif isinstance(o, list):
            # placeholder list to allow cycles
            nodes[uid] = {"t": "list", "v": []}
            # fill with references
            vals = []
            for item in o:
                if not _is_supported(item):
                    raise ValueError(f"Unsupported type: {type(item)!r}")
                vals.append(add(item))
            nodes[uid]["v"] = vals
        elif isinstance(o, dict):
            # keys must be strings
            for k in o.keys():
                if not isinstance(k, str):
                    raise ValueError("Dict keys must be strings")
            nodes[uid] = {"t": "dict", "v": {}}
            mapping = {}
            for k, v in o.items():
                if not _is_supported(v):
                    raise ValueError(f"Unsupported type: {type(v)!r}")
                mapping[k] = add(v)
            nodes[uid]["v"] = mapping
        else:
            raise ValueError(f"Unsupported type: {type(o)!r}")
        return uid

    def _is_supported(x: Any) -> bool:
        return (x is None or isinstance(x, (bool, int, float, str, list, dict)))

    root_uid = add(obj)
    out = {"root": root_uid, "nodes": nodes}
    return json.dumps(out, separators=(",", ":"), ensure_ascii=False)


def decode(s: str) -> object:
    """Decode string produced by encode back into Python objects, preserving shared refs/cycles.

    Raises ValueError on malformed input.
    """
    try:
        data = json.loads(s)
    except Exception as e:
        raise ValueError("Malformed input: not valid JSON") from e

    if not isinstance(data, dict):
        raise ValueError("Malformed input: top-level must be object")
    if "root" not in data or "nodes" not in data:
        raise ValueError("Malformed input: missing root or nodes")
    nodes = data["nodes"]
    root = data["root"]
    if not isinstance(nodes, dict):
        raise ValueError("Malformed input: nodes must be object")
    if root not in nodes:
        raise ValueError("Malformed input: root not in nodes")

    # First pass: validate structure and create placeholders
    placeholders = {}
    types = {}

    for uid, node in nodes.items():
        if not isinstance(uid, str):
            raise ValueError("Malformed input: node uid must be string")
        if not isinstance(node, dict):
            raise ValueError("Malformed input: node must be object")
        if "t" not in node or "v" not in node:
            raise ValueError("Malformed input: node missing t or v")
        t = node["t"]
        v = node["v"]
        types[uid] = t
        if t == "null":
            placeholders[uid] = None
        elif t == "bool":
            if not isinstance(v, bool):
                raise ValueError("Malformed input: bool node v must be boolean")
            placeholders[uid] = v
        elif t == "int":
            if not isinstance(v, int):
                raise ValueError("Malformed input: int node v must be integer")
            placeholders[uid] = v
        elif t == "float":
            if not (isinstance(v, float) or isinstance(v, int)):
                raise ValueError("Malformed input: float node v must be number")
            placeholders[uid] = float(v)
        elif t == "str":
            if not isinstance(v, str):
                raise ValueError("Malformed input: str node v must be string")
            placeholders[uid] = v
        elif t == "list":
            if not isinstance(v, list):
                raise ValueError("Malformed input: list node v must be array")
            # create empty list placeholder
            placeholders[uid] = []
        elif t == "dict":
            if not isinstance(v, dict):
                raise ValueError("Malformed input: dict node v must be object")
            # keys must be strings (json ensures), create empty dict placeholder
            placeholders[uid] = {}
        else:
            raise ValueError("Malformed input: unknown node type")

    # Second pass: fill containers resolving references
    for uid, node in nodes.items():
        t = node["t"]
        v = node["v"]
        if t == "list":
            lst = placeholders[uid]
            # v should be list of uids (strings)
            for ref in v:
                if not isinstance(ref, str) or ref not in placeholders:
                    raise ValueError("Malformed input: invalid reference in list")
                lst.append(placeholders[ref])
        elif t == "dict":
            dct = placeholders[uid]
            for k, ref in v.items():
                if not isinstance(k, str):
                    raise ValueError("Malformed input: dict key must be string")
                if not isinstance(ref, str) or ref not in placeholders:
                    raise ValueError("Malformed input: invalid reference in dict")
                dct[k] = placeholders[ref]
        # primitives already set

    return placeholders[root]

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def __init__(self):
        self.root = None

    def get_height(self, node):
        return 0 if node is None else node.height

    def get_balance(self, node):
        if node is None:
            return 0
        return self.get_height(node.left) - self.get_height(node.right)

    def right_rotate(self, y):
        x = y.left
        T2 = x.right
        # rotate
        x.right = y
        y.left = T2
        # update heights
        y.height = 1 + max(self.get_height(y.left), self.get_height(y.right))
        x.height = 1 + max(self.get_height(x.left), self.get_height(x.right))
        return x

    def left_rotate(self, x):
        y = x.right
        T2 = y.left
        # rotate
        y.left = x
        x.right = T2
        # update heights
        x.height = 1 + max(self.get_height(x.left), self.get_height(x.right))
        y.height = 1 + max(self.get_height(y.left), self.get_height(y.right))
        return y

    def insert(self, key: int) -> None:
        self.root = self._insert(self.root, key)

    def _insert(self, node, key):
        # normal BST insert
        if node is None:
            return Node(key)
        if key < node.val:
            node.left = self._insert(node.left, key)
        elif key > node.val:
            node.right = self._insert(node.right, key)
        else:
            # duplicate: no-op
            return node
        # update height
        node.height = 1 + max(self.get_height(node.left), self.get_height(node.right))
        # rebalance
        balance = self.get_balance(node)
        # LL
        if balance > 1 and key < node.left.val:
            return self.right_rotate(node)
        # RR
        if balance < -1 and key > node.right.val:
            return self.left_rotate(node)
        # LR
        if balance > 1 and key > node.left.val:
            node.left = self.left_rotate(node.left)
            return self.right_rotate(node)
        # RL
        if balance < -1 and key < node.right.val:
            node.right = self.right_rotate(node.right)
            return self.left_rotate(node)
        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def delete(self, key: int) -> None:
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return None
        # BST delete
        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            # node with one or no child
            if node.left is None:
                temp = node.right
                node = None
                return temp
            elif node.right is None:
                temp = node.left
                node = None
                return temp
            # node with two children: get inorder successor
            temp = self._min_value_node(node.right)
            node.val = temp.val
            node.right = self._delete(node.right, temp.val)
        # if the tree had only one node
        if node is None:
            return None
        # update height
        node.height = 1 + max(self.get_height(node.left), self.get_height(node.right))
        # rebalance
        balance = self.get_balance(node)
        # Left heavy
        if balance > 1:
            # Left-Left
            if self.get_balance(node.left) >= 0:
                return self.right_rotate(node)
            # Left-Right
            else:
                node.left = self.left_rotate(node.left)
                return self.right_rotate(node)
        # Right heavy
        if balance < -1:
            # Right-Right
            if self.get_balance(node.right) <= 0:
                return self.left_rotate(node)
            # Right-Left
            else:
                node.right = self.right_rotate(node.right)
                return self.left_rotate(node)
        return node

    def contains(self, key: int) -> bool:
        cur = self.root
        while cur is not None:
            if key == cur.val:
                return True
            elif key < cur.val:
                cur = cur.left
            else:
                cur = cur.right
        return False

import re


def evaluate(expr: str) -> float:
    if expr is None:
        raise ValueError("Empty expression")
    s = expr
    i = 0
    n = len(s)
    tokens = []  # list of (type, value)

    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            if j < n and s[j] == '.':
                j2 = j + 1
                if j2 >= n or not s[j2].isdigit():
                    # decimal point must be followed by a digit
                    raise ValueError("Invalid number")
                j = j2
                while j < n and s[j].isdigit():
                    j += 1
            num_text = s[i:j]
            tokens.append(('NUM', float(num_text)))
            i = j
            continue
        # two-char operator **
        if ch == '*' and i + 1 < n and s[i + 1] == '*':
            tokens.append(('OP', '**'))
            i += 2
            continue
        if ch in '+-*/%()':
            if ch == '(':
                tokens.append(('LPAREN', ch))
            elif ch == ')':
                tokens.append(('RPAREN', ch))
            else:
                tokens.append(('OP', ch))
            i += 1
            continue
        # any other char is invalid
        raise ValueError(f"Invalid token: {ch}")

    if not tokens:
        raise ValueError("Empty expression")

    # Parser
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return ('EOF', None)

        def pop(self):
            tok = self.peek()
            self.pos += 1
            return tok

        def expect(self, kind, value=None):
            tok = self.peek()
            if tok[0] != kind or (value is not None and tok[1] != value):
                raise ValueError('Unexpected token')
            self.pop()

        def parse_expression(self):
            return self.parse_add_sub()

        def parse_add_sub(self):
            left = self.parse_mul_div()
            while True:
                tok = self.peek()
                if tok[0] == 'OP' and tok[1] in ('+', '-'):
                    op = tok[1]
                    self.pop()
                    right = self.parse_mul_div()
                    if op == '+':
                        left = left + right
                    else:
                        left = left - right
                else:
                    break
            return left

        def parse_mul_div(self):
            left = self.parse_unary()
            while True:
                tok = self.peek()
                if tok[0] == 'OP' and tok[1] in ('*', '/', '%'):
                    op = tok[1]
                    self.pop()
                    right = self.parse_unary()
                    if op == '*':
                        left = left * right
                    elif op == '/':
                        if right == 0:
                            raise ValueError('Division by zero')
                        left = left / right
                    elif op == '%':
                        if right == 0:
                            raise ValueError('Modulo by zero')
                        left = left % right
                else:
                    break
            return left

        def parse_unary(self):
            tok = self.peek()
            if tok[0] == 'OP' and tok[1] in ('+', '-'):
                op = tok[1]
                self.pop()
                val = self.parse_unary()
                return val if op == '+' else -val
            return self.parse_power()

        def parse_power(self):
            # base is primary
            left = self.parse_primary()
            tok = self.peek()
            if tok[0] == 'OP' and tok[1] == '**':
                self.pop()
                # right operand should be parsed as unary (so 2**-1 works)
                right = self.parse_unary()
                # right-associative: compute left ** right
                # However for chains like a**b**c, the recursion via parse_unary->parse_power handles it
                left = left ** right
            return left

        def parse_primary(self):
            tok = self.peek()
            if tok[0] == 'NUM':
                self.pop()
                return tok[1]
            if tok[0] == 'LPAREN':
                self.pop()
                val = self.parse_expression()
                if self.peek()[0] != 'RPAREN':
                    raise ValueError('Unbalanced parentheses')
                self.pop()
                return val
            raise ValueError('Unexpected token in primary')

    p = Parser(tokens)
    try:
        result = p.parse_expression()
    except IndexError:
        raise ValueError('Invalid expression')

    # after parsing ensure no leftover tokens
    if p.peek()[0] != 'EOF':
        # if only leftover is RPAREN or LPAREN or operator, it's an error
        raise ValueError('Invalid trailing tokens')

    try:
        return float(result)
    except Exception:
        raise ValueError('Could not compute result')

from collections import defaultdict, deque
import heapq


def critical_path(durations: dict, deps: list) -> tuple:
    # If durations is empty, return as specified
    if not durations:
        return (0.0, [])

    # Collect all nodes from durations and deps
    nodes = set(durations.keys())
    for a, b in deps:
        nodes.add(a)
        nodes.add(b)

    # Ensure duration default for nodes not in durations
    dur = {n: float(durations.get(n, 0.0)) for n in nodes}

    # Build graph: adjacency list and predecessors
    adj = defaultdict(list)
    preds = defaultdict(list)
    indeg = {n: 0 for n in nodes}
    for a, b in deps:
        adj[a].append(b)
        preds[b].append(a)
        indeg[b] = indeg.get(b, 0) + 1
        # ensure a in indeg (may have been inserted from durations)
        if a not in indeg:
            indeg[a] = indeg.get(a, 0)

    # Kahn's algorithm for topo sort with deterministic ordering
    # Use a heap with string-key tie-break to be deterministic across runs
    heap = []
    for n in nodes:
        if indeg.get(n, 0) == 0:
            heapq.heappush(heap, (str(n), n))

    topo = []
    while heap:
        _, n = heapq.heappop(heap)
        topo.append(n)
        for m in adj.get(n, ()):  # neighbors
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, (str(m), m))

    if len(topo) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    # Compute earliest finish times: for each node, dur + max(earliest_finish of preds)
    ef = {n: 0.0 for n in nodes}
    for n in topo:
        if not preds[n]:
            ef[n] = dur[n]
        else:
            # choose max over predecessors
            max_pred = max((ef[p] for p in preds[n]), default=0.0)
            ef[n] = dur[n] + max_pred

    # Project duration is max ef
    project_duration = max(ef.values()) if ef else 0.0

    # Find one node that attains project_duration (deterministically pick smallest str key)
    candidates = [n for n, v in ef.items() if abs(v - project_duration) < 1e-12]
    if not candidates:
        return (float(project_duration), [])
    # pick deterministic candidate
    end = sorted(candidates, key=lambda x: str(x))[0]

    # Reconstruct one critical path by backtracking: at each step pick predecessor
    # that satisfies ef[cur] == dur[cur] + ef[pred]. If multiple, pick pred with largest ef,
    # tie-break deterministically by str(pred).
    path = []
    cur = end
    while True:
        path.append(cur)
        if not preds[cur]:
            break
        # select predecessors satisfying the equality
        valid_preds = [p for p in preds[cur] if abs(ef[cur] - (dur[cur] + ef[p])) < 1e-12]
        if not valid_preds:
            # should not happen, but break defensively
            break
        # choose the pred with maximum ef, tie-break by str
        valid_preds.sort(key=lambda x: ( -ef[x], str(x) ))
        cur = valid_preds[0]
    path.reverse()
    return (float(project_duration), path)

def brainfuck(code: str, input_str: str = "") -> str:
    """
    Execute a Brainfuck program given by `code` with optional input string `input_str`.

    Tape: 30,000 cells initialized to 0. Cells are Python ints with NO wraparound.
    Data pointer starts at 0. Allowed commands: > < + - . , [ ]
    Any other characters are ignored.

    For ',' reads the next character from input_str and stores its ord() value in the current cell;
    if input is exhausted stores 0.

    For '.' appends chr(current cell) to output (may raise if value outside valid range).

    Raises ValueError if brackets are unbalanced.
    """
    # Precompute matching brackets
    open_stack = []
    jump = {}
    for i, ch in enumerate(code):
        if ch == '[':
            open_stack.append(i)
        elif ch == ']':
            if not open_stack:
                raise ValueError("Unmatched closing bracket at position {}".format(i))
            j = open_stack.pop()
            jump[j] = i
            jump[i] = j
    if open_stack:
        # unmatched opening bracket(s)
        raise ValueError("Unmatched opening bracket(s)")

    tape = [0] * 30000
    dp = 0  # data pointer
    ip = 0  # instruction pointer
    inp_pos = 0
    output_chars = []
    n = len(code)

    while ip < n:
        cmd = code[ip]
        if cmd == '>':
            dp += 1
            if dp >= len(tape) or dp < 0:
                raise IndexError("Data pointer moved out of tape bounds")
        elif cmd == '<':
            dp -= 1
            if dp >= len(tape) or dp < 0:
                raise IndexError("Data pointer moved out of tape bounds")
        elif cmd == '+':
            tape[dp] += 1
        elif cmd == '-':
            tape[dp] -= 1
        elif cmd == '.':
            output_chars.append(chr(tape[dp]))
        elif cmd == ',':
            if inp_pos < len(input_str):
                tape[dp] = ord(input_str[inp_pos])
                inp_pos += 1
            else:
                tape[dp] = 0
        elif cmd == '[':
            if tape[dp] == 0:
                # jump forward to matching ] (jump maps [->])
                ip = jump[ip]
        elif cmd == ']':
            if tape[dp] != 0:
                # jump back to matching [ (jump maps ]->[), then continue from after it
                ip = jump[ip]
        # ignore any other characters
        ip += 1
    return ''.join(output_chars)

def parse_json(text: str) -> object:
    if not isinstance(text, str):
        raise ValueError('input must be a string')
    n = len(text)
    pos = 0

    def skip_ws(i):
        while i < n and text[i] in ' \t\n\r':
            i += 1
        return i

    def parse_value(i):
        i = skip_ws(i)
        if i >= n:
            raise ValueError('Unexpected end of input while expecting a value')
        ch = text[i]
        if ch == '{':
            return parse_object(i)
        if ch == '[':
            return parse_array(i)
        if ch == '"':
            return parse_string(i)
        if ch == 't' and text.startswith('true', i):
            return True, i + 4
        if ch == 'f' and text.startswith('false', i):
            return False, i + 5
        if ch == 'n' and text.startswith('null', i):
            return None, i + 4
        # number
        if ch == '-' or ch.isdigit():
            return parse_number(i)
        raise ValueError(f'Invalid value starting at position {i}')

    def parse_object(i):
        # assumes text[i] == '{'
        i += 1
        i = skip_ws(i)
        obj = {}
        if i < n and text[i] == '}':
            return obj, i + 1
        while True:
            i = skip_ws(i)
            if i >= n or text[i] != '"':
                raise ValueError('Expected string for object key')
            key, i = parse_string(i)
            i = skip_ws(i)
            if i >= n or text[i] != ':':
                raise ValueError('Expected colon after object key')
            i += 1
            val, i = parse_value(i)
            obj[key] = val
            i = skip_ws(i)
            if i >= n:
                raise ValueError('Unterminated object')
            if text[i] == ',':
                # lookahead to forbid trailing comma before closing brace
                i += 1
                i = skip_ws(i)
                if i < n and text[i] == '}':
                    raise ValueError('Trailing comma in object')
                continue
            if text[i] == '}':
                return obj, i + 1
            raise ValueError('Expected comma or closing brace in object')

    def parse_array(i):
        # assumes text[i] == '['
        i += 1
        i = skip_ws(i)
        arr = []
        if i < n and text[i] == ']':
            return arr, i + 1
        while True:
            val, i = parse_value(i)
            arr.append(val)
            i = skip_ws(i)
            if i >= n:
                raise ValueError('Unterminated array')
            if text[i] == ',':
                i += 1
                i = skip_ws(i)
                if i < n and text[i] == ']':
                    raise ValueError('Trailing comma in array')
                continue
            if text[i] == ']':
                return arr, i + 1
            raise ValueError('Expected comma or closing bracket in array')

    def parse_string(i):
        # assumes text[i] == '"'
        i += 1
        chars = []
        while True:
            if i >= n:
                raise ValueError('Unterminated string')
            ch = text[i]
            if ch == '"':
                i += 1
                return ''.join(chars), i
            if ch == '\\':
                i += 1
                if i >= n:
                    raise ValueError('Unterminated escape')
                esc = text[i]
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    # expect exactly 4 hex digits
                    if i + 4 >= n:
                        raise ValueError('Invalid unicode escape')
                    hex_digits = text[i+1:i+5]
                    if len(hex_digits) != 4 or any(c not in '0123456789abcdefABCDEF' for c in hex_digits):
                        raise ValueError('Invalid unicode escape')
                    codepoint = int(hex_digits, 16)
                    chars.append(chr(codepoint))
                    i += 4
                else:
                    raise ValueError('Invalid escape character')
                i += 1
                continue
            # disallow raw control characters
            if ord(ch) <= 0x1F:
                raise ValueError('Unescaped control character in string')
            chars.append(ch)
            i += 1

    def parse_number(i):
        start = i
        if text[i] == '-':
            i += 1
            if i >= n:
                raise ValueError('Invalid number')
        # integer part
        if i < n and text[i] == '0':
            i += 1
            # leading zero must not be followed by digit
            if i < n and text[i].isdigit():
                raise ValueError('Leading zeros are not allowed')
        else:
            if i >= n or not text[i].isdigit():
                raise ValueError('Invalid number')
            while i < n and text[i].isdigit():
                i += 1
        is_float = False
        # fraction
        if i < n and text[i] == '.':
            is_float = True
            i += 1
            if i >= n or not text[i].isdigit():
                raise ValueError('Invalid number: digits required after decimal point')
            while i < n and text[i].isdigit():
                i += 1
        # exponent
        if i < n and (text[i] == 'e' or text[i] == 'E'):
            is_float = True
            i += 1
            if i < n and (text[i] == '+' or text[i] == '-'):
                i += 1
            if i >= n or not text[i].isdigit():
                raise ValueError('Invalid number: bad exponent')
            while i < n and text[i].isdigit():
                i += 1
        num_text = text[start:i]
        try:
            if is_float:
                val = float(num_text)
            else:
                val = int(num_text)
        except Exception:
            raise ValueError('Invalid number')
        return val, i

    pos = skip_ws(0)
    if pos >= n:
        raise ValueError('Empty input')
    value, pos = parse_value(pos)
    pos = skip_ws(pos)
    if pos != n:
        raise ValueError('Trailing data')
    return value

import json
from typing import Any, Dict


def encode(obj: object) -> str:
    """Serialize object graph preserving shared references and cycles.
    Supported types: int, float, bool, None, str, list, dict (string keys).
    """
    # Use id(obj) to track identity
    next_id = 0
    id_map: Dict[int, int] = {}  # mapping from id(obj) -> node id
    obj_map: Dict[int, object] = {}  # mapping from id(obj) -> object
    nodes = []
    queue = [obj]

    while queue:
        cur = queue.pop(0)
        cur_key = id(cur)
        if cur_key in id_map:
            continue
        # Assign id
        nid = next_id
        next_id += 1
        id_map[cur_key] = nid
        obj_map[cur_key] = cur

        # Determine type
        if cur is None:
            ntype = "null"
            nvalue = None
        elif isinstance(cur, bool):
            ntype = "bool"
            nvalue = cur
        elif isinstance(cur, int):
            ntype = "int"
            nvalue = cur
        elif isinstance(cur, float):
            ntype = "float"
            nvalue = cur
        elif isinstance(cur, str):
            ntype = "str"
            nvalue = cur
        elif isinstance(cur, list):
            ntype = "list"
            # For lists store child ids (assign ids lazily)
            child_ids = []
            for item in cur:
                if not (isinstance(item, (int, float, bool, str, list, dict)) or item is None):
                    raise ValueError(f"Unsupported type in list: {type(item)}")
                queue.append(item)
                # child id may not yet be assigned; we will set placeholder using id(item)
                child_ids.append(id(item))
            nvalue = child_ids
        elif isinstance(cur, dict):
            ntype = "dict"
            d = {}
            for k, v in cur.items():
                if not isinstance(k, str):
                    raise ValueError("Dict keys must be strings")
                if not (isinstance(v, (int, float, bool, str, list, dict)) or v is None):
                    raise ValueError(f"Unsupported type in dict: {type(v)}")
                queue.append(v)
                d[k] = id(v)
            nvalue = d
        else:
            raise ValueError(f"Unsupported type: {type(cur)}")

        nodes.append({"id": nid, "type": ntype, "value": nvalue})

    # Now nodes contain entries with value referencing children by Python id. We need to replace those with node ids.
    # Build reverse map from obj id -> assigned node id
    reverse = id_map  # name alias

    # Convert node values
    out_nodes = []
    # Sort nodes by their assigned node id to ensure deterministic output
    nodes.sort(key=lambda n: n["id"])
    for node in nodes:
        ntype = node["type"]
        nvalue = node["value"]
        nid = node["id"]
        if ntype == "list":
            # nvalue is list of object ids
            child_node_ids = []
            for objid in nvalue:
                if objid not in reverse:
                    # This should not happen
                    raise ValueError("Internal encoding error: unknown child")
                child_node_ids.append(reverse[objid])
            out_nodes.append({"id": nid, "type": "list", "value": child_node_ids})
        elif ntype == "dict":
            d = {}
            for k, objid in nvalue.items():
                if objid not in reverse:
                    raise ValueError("Internal encoding error: unknown child")
                d[k] = reverse[objid]
            out_nodes.append({"id": nid, "type": "dict", "value": d})
        else:
            # primitives
            out_nodes.append({"id": nid, "type": ntype, "value": nvalue})

    payload = {"nodes": out_nodes, "root": id_map[id(obj)]}
    return json.dumps(payload, ensure_ascii=False)


def decode(s: str) -> object:
    """Decode string produced by encode back into object graph preserving identity and cycles."""
    try:
        payload = json.loads(s)
    except Exception as e:
        raise ValueError("Malformed input: not valid JSON") from e

    if not isinstance(payload, dict):
        raise ValueError("Malformed input: expected object")
    if "nodes" not in payload or "root" not in payload:
        raise ValueError("Malformed input: missing keys")
    nodes = payload["nodes"]
    root = payload["root"]
    if not isinstance(nodes, list):
        raise ValueError("Malformed input: nodes must be a list")
    # Build id->node map
    node_map: Dict[int, Dict[str, Any]] = {}
    for entry in nodes:
        if not isinstance(entry, dict):
            raise ValueError("Malformed input: node entry must be object")
        if "id" not in entry or "type" not in entry or "value" not in entry:
            raise ValueError("Malformed input: node missing fields")
        nid = entry["id"]
        if not isinstance(nid, int):
            raise ValueError("Malformed input: node id must be int")
        if nid in node_map:
            raise ValueError("Malformed input: duplicate node id")
        node_map[nid] = entry

    if not isinstance(root, int) or root not in node_map:
        raise ValueError("Malformed input: invalid root id")

    # Create placeholders
    placeholders: Dict[int, object] = {}
    for nid, entry in node_map.items():
        ntype = entry["type"]
        value = entry["value"]
        if ntype == "null":
            placeholders[nid] = None
        elif ntype == "bool":
            if not isinstance(value, bool):
                raise ValueError("Malformed input: bool node value not bool")
            placeholders[nid] = value
        elif ntype == "int":
            if not isinstance(value, int) or isinstance(value, bool):
                # bools are instances of int in JSON -> but JSON true/false map to bool, so this protects
                raise ValueError("Malformed input: int node value not int")
            placeholders[nid] = value
        elif ntype == "float":
            if not (isinstance(value, float) or isinstance(value, int)):
                # JSON may represent floats as ints if whole number
                raise ValueError("Malformed input: float node value not float")
            placeholders[nid] = float(value)
        elif ntype == "str":
            if not isinstance(value, str):
                raise ValueError("Malformed input: str node value not string")
            placeholders[nid] = value
        elif ntype == "list":
            if not isinstance(value, list):
                raise ValueError("Malformed input: list node value not list")
            placeholders[nid] = []
        elif ntype == "dict":
            if not isinstance(value, dict):
                raise ValueError("Malformed input: dict node value not object")
            # Ensure keys are strings
            for k in value.keys():
                if not isinstance(k, str):
                    raise ValueError("Malformed input: dict node has non-string key")
            placeholders[nid] = {}
        else:
            raise ValueError("Malformed input: unknown node type")

    # Second pass: fill composite nodes
    for nid, entry in node_map.items():
        ntype = entry["type"]
        value = entry["value"]
        if ntype == "list":
            # value is list of node ids
            lst = placeholders[nid]
            assert isinstance(lst, list)
            for cid in value:
                if not isinstance(cid, int) or cid not in placeholders:
                    raise ValueError("Malformed input: invalid child id in list")
                lst.append(placeholders[cid])
        elif ntype == "dict":
            dct = placeholders[nid]
            assert isinstance(dct, dict)
            for k, cid in value.items():
                if not isinstance(cid, int) or cid not in placeholders:
                    raise ValueError("Malformed input: invalid child id in dict")
                dct[k] = placeholders[cid]
        # primitives already set

    return placeholders[root]

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.height = 1  # height of subtree rooted at this node (leaf = 1)

class AVLTree:
    def __init__(self):
        self.root = None

    def contains(self, key: int) -> bool:
        cur = self.root
        while cur is not None:
            if key == cur.val:
                return True
            elif key < cur.val:
                cur = cur.left
            else:
                cur = cur.right
        return False

    def insert(self, key: int) -> None:
        def get_height(n):
            return n.height if n is not None else 0

        def update_height(n):
            n.height = 1 + max(get_height(n.left), get_height(n.right))

        def rotate_right(y):
            x = y.left
            T2 = x.right
            # rotation
            x.right = y
            y.left = T2
            # update heights
            update_height(y)
            update_height(x)
            return x

        def rotate_left(x):
            y = x.right
            T2 = y.left
            # rotation
            y.left = x
            x.right = T2
            # update heights
            update_height(x)
            update_height(y)
            return y

        def get_balance(n):
            return 0 if n is None else get_height(n.left) - get_height(n.right)

        def _insert(node, key):
            if node is None:
                return Node(key)
            if key == node.val:
                return node  # ignore duplicates
            elif key < node.val:
                node.left = _insert(node.left, key)
            else:
                node.right = _insert(node.right, key)

            update_height(node)
            balance = get_balance(node)

            # Left heavy
            if balance > 1:
                if key < node.left.val:
                    # Left Left
                    return rotate_right(node)
                else:
                    # Left Right
                    node.left = rotate_left(node.left)
                    return rotate_right(node)
            # Right heavy
            if balance < -1:
                if key > node.right.val:
                    # Right Right
                    return rotate_left(node)
                else:
                    # Right Left
                    node.right = rotate_right(node.right)
                    return rotate_left(node)

            return node

        self.root = _insert(self.root, key)
        return None

    def delete(self, key: int) -> None:
        def get_height(n):
            return n.height if n is not None else 0

        def update_height(n):
            n.height = 1 + max(get_height(n.left), get_height(n.right))

        def rotate_right(y):
            x = y.left
            T2 = x.right
            x.right = y
            y.left = T2
            update_height(y)
            update_height(x)
            return x

        def rotate_left(x):
            y = x.right
            T2 = y.left
            y.left = x
            x.right = T2
            update_height(x)
            update_height(y)
            return y

        def get_balance(n):
            return 0 if n is None else get_height(n.left) - get_height(n.right)

        def min_value_node(n):
            cur = n
            while cur.left is not None:
                cur = cur.left
            return cur

        def _delete(node, key):
            if node is None:
                return None
            if key < node.val:
                node.left = _delete(node.left, key)
            elif key > node.val:
                node.right = _delete(node.right, key)
            else:
                # node to be deleted
                if node.left is None:
                    return node.right
                elif node.right is None:
                    return node.left
                else:
                    # two children: get inorder successor (smallest in right subtree)
                    temp = min_value_node(node.right)
                    node.val = temp.val
                    node.right = _delete(node.right, temp.val)

            # if we reached here node might be None after deletion of child
            if node is None:
                return None

            update_height(node)
            balance = get_balance(node)

            # Left heavy
            if balance > 1:
                # Left Left
                if get_balance(node.left) >= 0:
                    return rotate_right(node)
                else:
                    node.left = rotate_left(node.left)
                    return rotate_right(node)
            # Right heavy
            if balance < -1:
                # Right Right
                if get_balance(node.right) <= 0:
                    return rotate_left(node)
                else:
                    node.right = rotate_right(node.right)
                    return rotate_left(node)

            return node

        self.root = _delete(self.root, key)
        return None

import re
from typing import List, Tuple, Any

TOKEN_REGEX = re.compile(r"\s*(?:(\d+(?:\.\d+)?)|(\*\*)|(\+)|(-)|(\*)|(/)|(%)|(\()|(\)))")


def evaluate(expr: str) -> float:
    """Evaluate an infix arithmetic expression and return the numeric result as a float.

    Raises ValueError on invalid input or invalid operations (division/modulo by zero,
    unbalanced parentheses, invalid tokens, etc.).
    """
    try:
        if expr is None:
            raise ValueError("Empty expression")
        s = expr
        tokens: List[Tuple[str, Any]] = []
        i = 0
        length = len(s)
        # Tokenize by scanning to ensure invalid tokens are detected
        while i < length:
            m = TOKEN_REGEX.match(s, i)
            if not m:
                # If current char is whitespace, skip it, else invalid
                if s[i].isspace():
                    i += 1
                    continue
                raise ValueError("Invalid token")
            # matched groups: 1:number,2:**,3:+,4:-,5:*,6:/,7:%,8:(,9:)
            num, powop, plus, minus, mul, div, mod, lpar, rpar = m.groups()
            if num is not None:
                tokens.append(("NUMBER", float(num)))
            elif powop is not None:
                tokens.append(("POW", None))
            elif plus is not None:
                tokens.append(("PLUS", None))
            elif minus is not None:
                tokens.append(("MINUS", None))
            elif mul is not None:
                tokens.append(("MUL", None))
            elif div is not None:
                tokens.append(("DIV", None))
            elif mod is not None:
                tokens.append(("MOD", None))
            elif lpar is not None:
                tokens.append(("LPAREN", None))
            elif rpar is not None:
                tokens.append(("RPAREN", None))
            i = m.end()
        if not tokens:
            raise ValueError("Empty expression")

        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else ("EOF", None)

        def advance():
            nonlocal pos
            tok = peek()
            pos += 1
            return tok

        def expect(kind: str):
            tok = peek()
            if tok[0] != kind:
                raise ValueError(f"Expected {kind}")
            advance()

        # Grammar:
        # expr -> add_sub
        # add_sub -> mul_div ( (PLUS|MINUS) mul_div )*
        # mul_div -> unary ( (MUL|DIV|MOD) unary )*
        # unary -> PLUS unary | MINUS unary | power
        # power -> primary ( POW unary )?
        # primary -> NUMBER | LPAREN expr RPAREN

        def parse_primary() -> float:
            tok = peek()
            if tok[0] == "NUMBER":
                advance()
                return tok[1]
            if tok[0] == "LPAREN":
                advance()
                val = parse_expr()
                if peek()[0] != "RPAREN":
                    raise ValueError("Mismatched parenthesis")
                advance()
                return val
            raise ValueError("Expected number or '('")

        def parse_power() -> float:
            # primary (** unary)? with right-associativity
            base = parse_primary()
            if peek()[0] == "POW":
                advance()
                exponent = parse_unary()
                try:
                    return base ** exponent
                except Exception as e:
                    # re-raise as ValueError
                    raise ValueError("Invalid power operation")
            return base

        def parse_unary() -> float:
            tok = peek()
            if tok[0] == "PLUS":
                advance()
                return parse_unary()
            if tok[0] == "MINUS":
                advance()
                return -parse_unary()
            return parse_power()

        def parse_mul_div() -> float:
            val = parse_unary()
            while True:
                tok = peek()
                if tok[0] == "MUL":
                    advance()
                    rhs = parse_unary()
                    val = val * rhs
                elif tok[0] == "DIV":
                    advance()
                    rhs = parse_unary()
                    if rhs == 0:
                        raise ValueError("Division by zero")
                    val = val / rhs
                elif tok[0] == "MOD":
                    advance()
                    rhs = parse_unary()
                    if rhs == 0:
                        raise ValueError("Modulo by zero")
                    val = val % rhs
                else:
                    break
            return val

        def parse_add_sub() -> float:
            val = parse_mul_div()
            while True:
                tok = peek()
                if tok[0] == "PLUS":
                    advance()
                    val = val + parse_mul_div()
                elif tok[0] == "MINUS":
                    advance()
                    val = val - parse_mul_div()
                else:
                    break
            return val

        def parse_expr() -> float:
            return parse_add_sub()

        result = parse_expr()
        if peek()[0] != "EOF":
            # Extra tokens left like two numbers in a row or trailing operator
            raise ValueError("Unexpected token at end")
        return float(result)
    except ValueError:
        # Pass through intended ValueErrors
        raise
    except Exception as e:
        # Map other errors to ValueError
        raise ValueError(str(e))

from collections import deque


def critical_path(durations: dict, deps: list) -> tuple:
    # Return (project_duration, critical_path)
    # Copy durations to avoid mutating caller's dict
    if not durations:
        # If durations is empty, return (0.0, []) per spec
        return 0.0, []

    local_durations = dict(durations)

    # Collect all nodes, include ones appearing in deps
    for a, b in deps:
        if a not in local_durations:
            local_durations[a] = 0.0
        if b not in local_durations:
            local_durations[b] = 0.0

    nodes = list(local_durations.keys())

    # Build adjacency and indegree
    adj = {n: [] for n in nodes}
    indegree = {n: 0 for n in nodes}
    for a, b in deps:
        adj[a].append(b)
        indegree[b] += 1

    # Kahn's algorithm for topological sort
    q = deque([n for n in nodes if indegree[n] == 0])
    topo = []
    while q:
        n = q.popleft()
        topo.append(n)
        for m in adj[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                q.append(m)

    if len(topo) != len(nodes):
        raise ValueError("Dependency graph has a cycle")

    # Compute earliest start times (longest path in DAG)
    est = {n: 0.0 for n in nodes}
    for n in topo:
        finish = est[n] + float(local_durations[n])
        for m in adj[n]:
            if est[m] < finish:
                est[m] = finish

    # Project duration = max finish time
    finishes = {n: est[n] + float(local_durations[n]) for n in nodes}
    project_duration = max(finishes.values()) if finishes else 0.0

    # Find a sink node achieving project duration
    # Use first encountered in nodes order
    target = None
    for n in nodes:
        if abs(finishes[n] - project_duration) < 1e-12:
            target = n
            break

    if target is None:
        return float(project_duration), []

    # Build predecessors mapping for backtracking
    preds = {n: [] for n in nodes}
    for a, b in deps:
        preds[b].append(a)

    # Reconstruct one critical path by moving to any predecessor p
    # such that est[p] + dur[p] == est[cur]
    path_rev = [target]
    cur = target
    while True:
        found = False
        for p in preds[cur]:
            if abs((est[p] + float(local_durations[p])) - est[cur]) < 1e-12:
                path_rev.append(p)
                cur = p
                found = True
                break
        if not found:
            break

    path = list(reversed(path_rev))
    return float(project_duration), path

def brainfuck(code: str, input_str: str = "") -> str:
    tape = [0] * 30000
    data_ptr = 0
    code_ptr = 0
    output = []
    input_ptr = 0

    # Pre-process the code to find matching brackets
    bracket_map = {}
    temp_bracket_stack = []
    for i, char in enumerate(code):
        if char == '[':
            temp_bracket_stack.append(i)
        elif char == ']':
            if not temp_bracket_stack:
                raise ValueError("Unbalanced brackets")
            open_bracket_pos = temp_bracket_stack.pop()
            bracket_map[open_bracket_pos] = i
            bracket_map[i] = open_bracket_pos
    if temp_bracket_stack:
        raise ValueError("Unbalanced brackets")

    while code_ptr < len(code):
        command = code[code_ptr]

        if command == '>':
            data_ptr += 1
        elif command == '<':
            data_ptr -= 1
        elif command == '+':
            tape[data_ptr] += 1
        elif command == '-':
            tape[data_ptr] -= 1
        elif command == '.':
            output.append(chr(tape[data_ptr]))
        elif command == ',':
            if input_ptr < len(input_str):
                tape[data_ptr] = ord(input_str[input_ptr])
                input_ptr += 1
            else:
                tape[data_ptr] = 0
        elif command == '[':
            if tape[data_ptr] == 0:
                code_ptr = bracket_map[code_ptr]
        elif command == ']':
            if tape[data_ptr] != 0:
                code_ptr = bracket_map[code_ptr]

        code_ptr += 1
    return "".join(output)

import re

def parse_json(text):
    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    def parse_value(s, i):
        i = skip_whitespace(s, i)
        res, new_i = parse_literal(s, i)
        if res is not None:
            return res, new_i
        res, new_i = parse_string(s, i)
        if res is not None:
            return res, new_i
        res, new_i = parse_number(s, i)
        if res is not None:
            return res, new_i
        res, new_i = parse_object(s, i)
        if res is not None:
            return res, new_i
        res, new_i = parse_array(s, i)
        if res is not None:
            return res, new_i
        return None, i

    def parse_string(s, i):
        if i >= len(s) or s[i] != '"':
            return None, i
        i += 1
        result = []
        while i < len(s):
            if s[i] == '"':
                return "".join(result), i + 1
            elif s[i] == '\\':
                i += 1
                if i >= len(s):
                    raise ValueError("Unterminated string")
                if s[i] == '"':
                    result.append('"')
                elif s[i] == '\\':
                    result.append('\\')
                elif s[i] == '/':
                    result.append('/')
                elif s[i] == 'b':
                    result.append('\b')
                elif s[i] == 'f':
                    result.append('\f')
                elif s[i] == 'n':
                    result.append('\n')
                elif s[i] == 'r':
                    result.append('\r')
                elif s[i] == 't':
                    result.append('\t')
                elif s[i] == 'u':
                    if i + 4 >= len(s):
                        raise ValueError("Invalid unicode escape")
                    hex_code = s[i+1:i+5]
                    if not re.fullmatch(r"[0-9a-fA-F]{4}", hex_code):
                        raise ValueError("Invalid unicode escape")
                    result.append(chr(int(hex_code, 16)))
                    i += 4
                else:
                    raise ValueError("Invalid escape sequence")
            elif ord(s[i]) < 32:
                raise ValueError("Unescaped control character")
            else:
                result.append(s[i])
            i += 1
        raise ValueError("Unterminated string")

    def parse_number(s, i):
        match = re.match(r"^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?", s[i:])
        if match:
            num_str = match.group(0)
            # No need for these checks, regex handles them
            # if num_str == '-' or num_str == '+' or num_str.endswith('.') or num_str.endswith('e') or num_str.endswith('E') or num_str.endswith('e-') or num_str.endswith('e+') or num_str.endswith('E-') or num_str.endswith('E+'):
            #     raise ValueError("Invalid number format")

            i += len(num_str)
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str), i
            return int(num_str), i
        return None, i

    def parse_object(s, i):
        if i >= len(s) or s[i] != '{':
            return None, i
        i += 1
        obj = {}
        i = skip_whitespace(s, i)
        if i >= len(s):
            raise ValueError("Unterminated object")
        if s[i] == '}':
            return obj, i + 1
        while True:
            key, i = parse_string(s, i)
            if key is None:
                raise ValueError("Expected string key")
            i = skip_whitespace(s, i)
            if i >= len(s) or s[i] != ':':
                raise ValueError("Expected ':'")
            i += 1
            i = skip_whitespace(s, i)
            value, i = parse_value(s, i)
            if value is None:
                raise ValueError("Expected value")
            obj[key] = value
            i = skip_whitespace(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] == '}':
                return obj, i + 1
            if s[i] != ',':
                raise ValueError("Expected ',' or '}'")
            i += 1
            i = skip_whitespace(s, i)

    def parse_array(s, i):
        if i >= len(s) or s[i] != '[':
            return None, i
        i += 1
        arr = []
        i = skip_whitespace(s, i)
        if i >= len(s):
            raise ValueError("Unterminated array")
        if s[i] == ']':
            return arr, i + 1
        while True:
            value, i = parse_value(s, i)
            if value is None:
                raise ValueError("Expected value")
            arr.append(value)
            i = skip_whitespace(s, i)
            if i >= len(s):
                raise ValueError("Unterminated array")
            if s[i] == ']':
                return arr, i + 1
            if s[i] != ',':
                raise ValueError("Expected ',' or ']'")
            i += 1
            i = skip_whitespace(s, i)

    def parse_literal(s, i):
        if s[i:].startswith('true'):
            return True, i + 4
        if s[i:].startswith('false'):
            return False, i + 5
        if s[i:].startswith('null'):
            return None, i + 4
        return None, i

    def skip_whitespace(s, i):
        while i < len(s) and s[i].isspace():
            i += 1
        return i

    value, end_index = parse_value(text, 0)
    if value is None and text.strip() not in ["null", "true", "false", "[]", "{}"]:
        raise ValueError("Invalid JSON input")
    end_index = skip_whitespace(text, end_index)
    if end_index != len(text):
        raise ValueError("Trailing content after JSON value")
    return value

