import re

def full_match(pattern, text):
    try:
        compiled_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(str(e))

    match = compiled_pattern.fullmatch(text)
    return match is not None

import json

class GraphSerializer:
    def __init__(self):
        self.objects = []
        self.id_map = {}

    def encode(self, obj):
        self.objects = []
        self.id_map = {}
        self._encode_recursive(obj)
        return json.dumps(self.objects)

    def _encode_recursive(self, obj):
        obj_id = id(obj)
        if obj_id in self.id_map:
            return {"__ref__": self.id_map[obj_id]}

        idx = len(self.objects)
        self.id_map[obj_id] = idx

        if isinstance(obj, (int, float, bool, type(None), str)):
            self.objects.append(obj)
            return obj
        elif isinstance(obj, list):
            encoded_list = []
            self.objects.append(encoded_list)
            for item in obj:
                encoded_list.append(self._encode_recursive(item))
            return {"__list__": idx}
        elif isinstance(obj, dict):
            encoded_dict = {}
            self.objects.append(encoded_dict)
            for key, value in obj.items():
                if not isinstance(key, str):
                    raise ValueError("Dict keys must be strings.")
                encoded_dict[key] = self._encode_recursive(value)
            return {"__dict__": idx}
        else:
            raise ValueError(f"Unsupported type: {type(obj)}")

    def decode(self, s):
        self.objects = []
        self.id_map = {}
        encoded_objects = json.loads(s)

        # First pass: create all objects
        for i, item in enumerate(encoded_objects):
            if isinstance(item, dict) and "__list__" in item:
                self.objects.append([])
            elif isinstance(item, dict) and "__dict__" in item:
                self.objects.append({})
            else:
                self.objects.append(item)

        # Second pass: populate lists and dicts, resolve references
        for i, item in enumerate(encoded_objects):
            if isinstance(item, dict) and "__list__" in item:
                original_list_idx = item["__list__"]
                decoded_list = self.objects[original_list_idx]
                for encoded_item in encoded_objects[original_list_idx]:
                    decoded_list.append(self._decode_recursive(encoded_item))
            elif isinstance(item, dict) and "__dict__" in item:
                original_dict_idx = item["__dict__"]
                decoded_dict = self.objects[original_dict_idx]
                for key, encoded_value in encoded_objects[original_dict_idx].items():
                    decoded_dict[key] = self._decode_recursive(encoded_value)

        return self.objects[0]

    def _decode_recursive(self, obj):
        if isinstance(obj, dict) and "__ref__" in obj:
            return self.objects[obj["__ref__"]]
        elif isinstance(obj, dict) and "__list__" in obj:
            return self.objects[obj["__list__"]]
        elif isinstance(obj, dict) and "__dict__" in obj:
            return self.objects[obj["__dict__"]]
        else:
            return obj

