class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def __init__(self):
        self.root = None

    def _height(self, node):
        if not node:
            return 0
        return node.height

    def _update_height(self, node):
        if node:
            node.height = 1 + max(self._height(node.left), self._height(node.right))

    def _get_balance(self, node):
        if not node:
            return 0
        return self._height(node.left) - self._height(node.right)

    def _right_rotate(self, y):
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        self._update_height(y)
        self._update_height(x)

        return x

    def _left_rotate(self, x):
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        self._update_height(x)
        self._update_height(y)

        return y

    def insert(self, key: int) -> None:
        self.root = self._insert(self.root, key)

    def _insert(self, node, key):
        if not node:
            return Node(key)

        if key < node.val:
            node.left = self._insert(node.left, key)
        elif key > node.val:
            node.right = self._insert(node.right, key)
        else:
            return node  # Duplicate keys are not allowed

        self._update_height(node)

        balance = self._get_balance(node)

        # Left Left Case
        if balance > 1 and key < node.left.val:
            return self._right_rotate(node)

        # Right Right Case
        if balance < -1 and key > node.right.val:
            return self._left_rotate(node)

        # Left Right Case
        if balance > 1 and key > node.left.val:
            node.left = self._left_rotate(node.left)
            return self._right_rotate(node)

        # Right Left Case
        if balance < -1 and key < node.right.val:
            node.right = self._right_rotate(node.right)
            return self._left_rotate(node)

        return node

    def delete(self, key: int) -> None:
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if not node:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if not node.left or not node.right:
                temp = node.left if node.left else node.right
                node = None
                return temp

            temp = self._min_value_node(node.right)
            node.val = temp.val
            node.right = self._delete(node.right, temp.val)

        if not node:
            return node

        self._update_height(node)

        balance = self._get_balance(node)

        # Left Left Case
        if balance > 1 and self._get_balance(node.left) >= 0:
            return self._right_rotate(node)

        # Left Right Case
        if balance > 1 and self._get_balance(node.left) < 0:
            node.left = self._left_rotate(node.left)
            return self._right_rotate(node)

        # Right Right Case
        if balance < -1 and self._get_balance(node.right) <= 0:
            return self._left_rotate(node)

        # Right Left Case
        if balance < -1 and self._get_balance(node.right) > 0:
            node.right = self._right_rotate(node.right)
            return self._left_rotate(node)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def contains(self, key: int) -> bool:
        return self._search(self.root, key) is not None

    def _search(self, node, key):
        if not node:
            return None
        if key == node.val:
            return node
        elif key < node.val:
            return self._search(node.left, key)
        else:
            return self._search(node.right, key)

    def search(self, key: int):
        return self._search(self.root, key)

def min_edit_ops(a: str, b: str) -> list[tuple]:
    n = len(a)
    m = len(b)

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # Deletion
                                   dp[i][j - 1],      # Insertion
                                   dp[i - 1][j - 1])  # Substitution

    # Backtrack to find the operations
    operations = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            i -= 1
            j -= 1
        elif i > 0 and j > 0 and dp[i][j] == dp[i - 1][j - 1] + 1:
            operations.append(('sub', i - 1, b[j - 1]))
            i -= 1
            j -= 1
        elif i > 0 and dp[i][j] == dp[i - 1][j] + 1:
            operations.append(('delete', i - 1))
            i -= 1
        elif j > 0 and dp[i][j] == dp[i][j - 1] + 1:
            operations.append(('insert', i, b[j - 1]))
            j -= 1

    operations.reverse()

    # Adjust indices for sequential operations
    final_operations = []
    current_offset = 0
    for op in operations:
        op_type = op[0]
        if op_type == 'delete':
            original_index = op[1]
            final_operations.append(('delete', original_index + current_offset))
            current_offset -= 1
        elif op_type == 'insert':
            original_index = op[1]
            char_to_insert = op[2]
            final_operations.append(('insert', original_index + current_offset, char_to_insert))
            current_offset += 1
        elif op_type == 'sub':
            original_index = op[1]
            char_to_sub = op[2]
            final_operations.append(('sub', original_index + current_offset, char_to_sub))

    return final_operations

import re

def evaluate(expression: str) -> float:
    tokens = tokenize(expression)
    postfix_tokens = shunting_yard(tokens)
    return evaluate_postfix(postfix_tokens)

def tokenize(expression: str) -> list:
    if not expression.strip():
        raise ValueError("Empty expression")

    # Regular expression to match numbers, operators, and parentheses
    # Numbers: integers, decimals (e.g., 3.5, 0.5, .5, 3.)
    # Operators: **, *, /, %, +, -
    # Parentheses: (, )
    token_pattern = re.compile(r'(\d+\.?\d*|\.?\d+|\*\*|[+\-*/%()])')

    tokens = []
    last_token_type = 'START' # 'START', 'NUMBER', 'OPERATOR', 'PAREN_OPEN', 'PAREN_CLOSE'

    for match in token_pattern.finditer(expression):
        token = match.group(0)

        if token.isspace():
            continue

        if re.fullmatch(r'\d+\.?\d*|\.?\d+', token):
            tokens.append(float(token))
            last_token_type = 'NUMBER'
        elif token in ['+', '-']:
            # Determine if it's a unary or binary operator
            if last_token_type in ['START', 'OPERATOR', 'PAREN_OPEN']:
                if token == '-':
                    tokens.append('UNARY_MINUS')
                else:
                    tokens.append('UNARY_PLUS')
            else:
                tokens.append(token)
            last_token_type = 'OPERATOR'
        elif token in ['*', '/', '%', '**']:
            tokens.append(token)
            last_token_type = 'OPERATOR'
        elif token == '(':
            tokens.append(token)
            last_token_type = 'PAREN_OPEN'
        elif token == ')':
            tokens.append(token)
            last_token_type = 'PAREN_CLOSE'
        else:
            raise ValueError(f"Invalid token: {token}")

    if not tokens:
        raise ValueError("Empty expression")

    return tokens

def shunting_yard(tokens: list) -> list:
    output_queue = []
    operator_stack = []

    precedence = {
        '**': 6, # Highest precedence
        'UNARY_PLUS': 5,
        'UNARY_MINUS': 5,
        '*': 4,
        '/': 4,
        '%': 4,
        '+': 3,
        '-': 3,
    }

    associativity = {
        '**': 'right',
        '*': 'left',
        '/': 'left',
        '%': 'left',
        '+': 'left',
        '-': 'left',
        'UNARY_PLUS': 'right',
        'UNARY_MINUS': 'right',
    }

    for token in tokens:
        if isinstance(token, float):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] != '(' and
                   ((associativity.get(token) == 'left' and precedence.get(operator_stack[-1]) >= precedence[token]) or
                    (associativity.get(token) == 'right' and precedence.get(operator_stack[-1]) > precedence[token]))):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop() # Pop '('
        else:
            raise ValueError(f"Unknown token during shunting yard: {token}")

    while operator_stack:
        if operator_stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output_queue.append(operator_stack.pop())

    return output_queue

def evaluate_postfix(tokens: list) -> float:
    operand_stack = []

    for token in tokens:
        if isinstance(token, float):
            operand_stack.append(token)
        else:
            if token == 'UNARY_MINUS':
                if not operand_stack:
                    raise ValueError("Invalid expression: unary minus needs an operand")
                operand = operand_stack.pop()
                operand_stack.append(-operand)
            elif token == 'UNARY_PLUS':
                if not operand_stack:
                    raise ValueError("Invalid expression: unary plus needs an operand")
                operand = operand_stack.pop()
                operand_stack.append(operand)
            else:
                if len(operand_stack) < 2:
                    raise ValueError("Invalid expression: operator needs two operands")
                operand2 = operand_stack.pop()
                operand1 = operand_stack.pop()

                if token == '+':
                    operand_stack.append(operand1 + operand2)
                elif token == '-':
                    operand_stack.append(operand1 - operand2)
                elif token == '*':
                    operand_stack.append(operand1 * operand2)
                elif token == '/':
                    if operand2 == 0:
                        raise ValueError("Division by zero")
                    operand_stack.append(operand1 / operand2)
                elif token == '%':
                    if operand2 == 0:
                        raise ValueError("Modulo by zero")
                    operand_stack.append(operand1 % operand2)
                elif token == '**':
                    operand_stack.append(operand1 ** operand2)
                else:
                    raise ValueError(f"Unknown operator during postfix evaluation: {token}")

    if len(operand_stack) != 1:
        raise ValueError("Invalid expression: too many operands or operators")

    return operand_stack[0]

def critical_path(durations: dict, deps: list) -> tuple:
    if not durations:
        return (0.0, [])

    # Build adjacency list and in-degree map
    adj = {task: [] for task in durations}
    in_degree = {task: 0 for task in durations}
    for u, v in deps:
        adj[u].append(v)
        in_degree[v] += 1

    # Topological sort (Kahn's algorithm)
    q = [task for task in durations if in_degree[task] == 0]
    topological_order = []
    while q:
        u = q.pop(0)
        topological_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    if len(topological_order) != len(durations):
        raise ValueError("Cycle detected in dependency graph")

    # Calculate earliest start times and longest path to each task
    earliest_start_time = {task: 0.0 for task in durations}
    longest_path_to = {task: [task] for task in durations}

    for u in topological_order:
        for v in adj[u]:
            if earliest_start_time[u] + durations[u] > earliest_start_time[v]:
                earliest_start_time[v] = earliest_start_time[u] + durations[u]
                longest_path_to[v] = longest_path_to[u] + [v]

    # Find project duration and critical path
    project_duration = 0.0
    critical_path_tasks = []
    for task in durations:
        finish_time = earliest_start_time[task] + durations[task]
        if finish_time > project_duration:
            project_duration = finish_time
            critical_path_tasks = longest_path_to[task]

    return (project_duration, critical_path_tasks)

def full_justify(words: list[str], max_width: int) -> list[str]:
    result = []
    current_line = []
    current_length = 0

    for word in words:
        # Check if adding the word to the current line exceeds max_width
        # current_length + len(word) + (1 if current_line else 0)
        # The (1 if current_line else 0) accounts for the space needed before the new word
        if current_length + len(word) + len(current_line) > max_width:
            result.append(format_line(current_line, current_length, max_width, False))
            current_line = [word]
            current_length = len(word)
        else:
            current_line.append(word)
            current_length += len(word)

    if current_line:
        result.append(format_line(current_line, current_length, max_width, True))

    return result

def format_line(words: list[str], current_length: int, max_width: int, is_last_line: bool) -> str:
    num_words = len(words)

    if is_last_line or num_words == 1:
        return " ".join(words).ljust(max_width)

    total_spaces_needed = max_width - current_length
    num_gaps = num_words - 1

    spaces_per_gap = total_spaces_needed // num_gaps
    extra_spaces = total_spaces_needed % num_gaps

    justified_line = ""
    for i in range(num_words):
        justified_line += words[i]
        if i < num_gaps:
            justified_line += " " * spaces_per_gap
            if i < extra_spaces:
                justified_line += " "
    return justified_line

