    token_pattern = re.compile(r'(\d+\.\d*|\d+|\*\*|//|==|!=|<=|>=|<<|>>|&&|\|\||[+\-*/%()]|[^\\s]+)')

    # Pre-process the expression to handle unary minus/plus.
    # This is a common trick: replace unary minus with a special token, e.g., 'U-'
    # and unary plus with 'U+'.
    # This needs to be done carefully to distinguish from binary operators.

    # Add spaces around operators and parentheses to make tokenization easier
    expression = re.sub(r'([+\-*/%()])', r' \\1 ', expression)
    expression = re.sub(r'(\*\*)', r' \\1 ', expression)

    # Replace multiple spaces with a single space
    expression = re.sub(r'\\s+', ' ', expression).strip()

    # Handle unary minus/plus
    # A unary minus/plus is at the beginning of the expression or after an opening parenthesis or another operator
    processed_expression = []
    i = 0
    while i < len(expression):
        char = expression[i]
        if char == '-' and (i == 0 or expression[i-1] in '(*+/-^%'):
            processed_expression.append('U-')
        elif char == '+' and (i == 0 or expression[i-1] in '(*+/-^%'):
            processed_expression.append('U+')
        else:
            processed_expression.append(char)
        i += 1

    expression = "".join(processed_expression)

    # Now, tokenize the processed expression
    tokens = [token for token in token_pattern.findall(expression) if token.strip()]

    if not tokens:
        raise ValueError("Empty expression")

    # Shunting-Yard Algorithm
    output_queue = []
    operator_stack = []

    precedence = {
        'U-': 5, 'U+': 5,
        '**': 4,
        '*': 3, '/': 3, '%': 3,
        '+': 2, '-': 2,
    }

    associativity = {
        '**': 'right',
        '*': 'left', '/': 'left', '%': 'left',
        '+': 'left', '-': 'left',
        'U-': 'right', 'U+': 'right' # Unary operators are typically right-associative
    }

    i = 0
    while i < len(tokens):
        token = tokens[i]
        if re.match(r'\\d+\\.?\\d*|\\.\\d+', token):  # Number
            output_queue.append(float(token))
        elif token in precedence:  # Operator
            while (operator_stack and operator_stack[-1] != '(' and
                   (precedence.get(operator_stack[-1]) > precedence[token] or
                    (precedence.get(operator_stack[-1]) == precedence[token] and associativity.get(token) == 'left'))):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop()  # Pop '('
        else:
            raise ValueError(f"Invalid token: {token}")
        i += 1

    while operator_stack:
        if operator_stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output_queue.append(operator_stack.pop())

