                    operand_stack.append(left / right)
                elif token == '%':
                    if right == 0:
                        raise ValueError("Modulo by zero")
                    operand_stack.append(left % right)
                elif token == '**':
                    operand_stack.append(left ** right)

    if len(operand_stack) != 1:
        raise ValueError("Invalid expression")

    return operand_stack[0]

