                # Parse value
                self.skip_whitespace()
                value = self.parse_value()

                # Add to object
                obj[key] = value

                # Check for comma or closing brace
                self.skip_whitespace()
                ch = self.peek()
                if ch == '}':
                    self.consume('}')
                    break
                elif ch == ',':
                    self.consume(',')
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError(f"Expected ',' or '}}', found '{ch}'")

            return obj

        def parse_array(self):
            """Parse a JSON array."""
            self.consume('[')
            self.skip_whitespace()

            arr = []

            # Check for empty array
            if self.peek() == ']':
                self.consume(']')
                return arr

            while True:
                # Parse value
                self.skip_whitespace()
                value = self.parse_value()
                arr.append(value)

                # Check for comma or closing bracket
                self.skip_whitespace()
                ch = self.peek()
                if ch == ']':
                    self.consume(']')
                    break
                elif ch == ',':
                    self.consume(',')
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError(f"Expected ',' or ']', found '{ch}'")

            return arr

        def parse_string(self):
            """Parse a JSON string."""
            self.consume('"')
            result = []

            while self.pos < self.length:
                ch = self.consume()
                if ch == '"':
                    return ''.join(result)
                elif ch == '\\':
                    # Escape sequence
                    if self.pos >= self.length:
                        raise ValueError("Incomplete escape sequence")
                    esc = self.consume()
                    if esc == '"':
                        result.append('"')
                    elif esc == '\\':
                        result.append('\\')
                    elif esc == '/':
                        result.append('/')
                    elif esc == 'b':
                        result.append('\b')
                    elif esc == 'f':
                        result.append('\f')
                    elif esc == 'n':
                        result.append('\n')
                    elif esc == 'r':
                        result.append('\r')
                    elif esc == 't':
                        result.append('\t')
                    elif esc == 'u':
                        # Unicode escape: \uXXXX
                        hex_digits = ''
                        for _ in range(4):
                            if self.pos >= self.length:
                                raise ValueError("Incomplete Unicode escape")
                            hex_ch = self.consume()
                            if not ('0' <= hex_ch <= '9' or 'a' <= hex_ch <= 'f' or 'A' <= hex_ch <= 'F'):
                                raise ValueError(f"Invalid hex digit in Unicode escape: '{hex_ch}'")
                            hex_digits += hex_ch
                        # Convert hex to Unicode character
                        try:
                            code_point = int(hex_digits, 16)
                            result.append(chr(code_point))
                        except ValueError:
                            raise ValueError(f"Invalid Unicode code point: \\u{hex_digits}")
                    else:
                        raise ValueError(f"Invalid escape sequence: \\{esc}")
                elif ord(ch) < 0x20:  # Control characters
                    raise ValueError(f"Control character in string: U+{ord(ch):04X}")
                else:
                    result.append(ch)

            raise ValueError("Unclosed string")

        def parse_null(self):
            """Parse the null literal."""
            self.consume('n')
            self.consume('u')
            self.consume('l')
            self.consume('l')
            return None

        def parse_true(self):
            """Parse the true literal."""
            self.consume('t')
            self.consume('r')
            self.consume('u')
            self.consume('e')
            return True

        def parse_false(self):
            """Parse the false literal."""
            self.consume('f')
            self.consume('a')
            self.consume('l')
            self.consume('s')
            self.consume('e')
            return False

        def parse_number(self):
            """Parse a JSON number."""
            start_pos = self.pos

            # Optional minus sign
            if self.peek() == '-':
                self.consume()

            # Integer part
            if self.peek() == '0':
                self.consume()
                # Check for leading zero (except 0 itself)
                if self.pos < self.length and '0' <= self.peek() <= '9':
                    raise ValueError("Number with leading zero")
            else:
                # At least one digit
                if self.pos >= self.length or not ('1' <= self.peek() <= '9'):
                    raise ValueError("Invalid number")
                while self.pos < self.length and '0' <= self.peek() <= '9':
                    self.consume()

            # Fraction part
            if self.pos < self.length and self.peek() == '.':
                self.consume()
                # At least one digit after decimal point
                if self.pos >= self.length or not ('0' <= self.peek() <= '9'):
                    raise ValueError("Invalid number: missing digits after decimal point")
                while self.pos < self.length and '0' <= self.peek() <= '9':
                    self.consume()

            # Exponent part
            if self.pos < self.length and self.peek() in 'eE':
                self.consume()
                # Optional sign
                if self.pos < self.length and self.peek() in '+-':
                    self.consume()
                # At least one digit
                if self.pos >= self.length or not ('0' <= self.peek() <= '9'):
                    raise ValueError("Invalid number: missing digits in exponent")
                while self.pos < self.length and '0' <= self.peek() <= '9':
                    self.consume()

            # Extract the number string and convert
            num_str = self.text[start_pos:self.pos]
            try:
                # Check if it's an integer or float
                if '.' in num_str or 'e' in num_str or 'E' in num_str:
                    return float(num_str)
                else:
                    return int(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")

        def parse(self):
            """Parse the entire JSON document."""
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Empty input")

            result = self.parse_value()

            # Check for trailing content
            self.skip_whitespace()
            if self.pos < self.length:
                raise ValueError("Trailing content after JSON value")

            return result

    parser = Parser(text)
    return parser.parse()

from typing import List, Optional, Tuple, Union

class Node:
    """Base class for regex nodes"""
    pass

class Literal(Node):
    def __init__(self, char: str):
        self.char = char

    def __repr__(self):
        return f"Literal('{self.char}')"

class AnyChar(Node):
    def __repr__(self):
        return "AnyChar()"

class CharClass(Node):
    def __init__(self, negated: bool, ranges: List[Tuple[str, str]]):
        self.negated = negated
        self.ranges = ranges  # list of (start, end) inclusive ranges

    def __repr__(self):
        return f"CharClass(negated={self.negated}, ranges={self.ranges})"

class Quantifier(Node):
    def __init__(self, node: Node, min_count: int, max_count: Optional[int]):
        self.node = node
        self.min_count = min_count  # 0 or 1
        self.max_count = max_count  # None for unlimited

    def __repr__(self):
        max_str = "inf" if self.max_count is None else self.max_count
        return f"Quantifier(node={self.node}, min={self.min_count}, max={max_str})"

class Group(Node):
    def __init__(self, nodes: List[Node]):
        self.nodes = nodes

    def __repr__(self):
        return f"Group({self.nodes})"

class Alternation(Node):
    def __init__(self, left: List[Node], right: List[Node]):
        self.left = left
        self.right = right

    def __repr__(self):
        return f"Alternation(left={self.left}, right={self.right})"

class AnchorStart(Node):
    def __repr__(self):
        return "AnchorStart()"

class AnchorEnd(Node):
    def __repr__(self):
        return "AnchorEnd()"

class Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0
        self.length = len(pattern)

    def parse(self) -> List[Node]:
        """Parse the entire pattern into a list of nodes"""
        nodes = []
        while self.pos < self.length:
            node = self.parse_atom()
            if node is None:
                break
            nodes.append(node)
        return nodes

    def parse_atom(self) -> Optional[Node]:
        """Parse a single atom (literal, ., char class, group, anchor, escape)"""
        if self.pos >= self.length:
            return None

        ch = self.pattern[self.pos]

        if ch == '^':
            self.pos += 1
            return AnchorStart()
        elif ch == '$':
            self.pos += 1
            return AnchorEnd()
        elif ch == '.':
            self.pos += 1
            return AnyChar()
        elif ch == '[':
            return self.parse_char_class()
        elif ch == '(':
            return self.parse_group()
        elif ch == '\\':
            return self.parse_escape()
        elif ch in '*+?':
            raise ValueError("Quantifier without preceding atom")
        elif ch == ')':
            # End of group, handled by parse_group
            return None
        elif ch == '|':
            # Alternation, handled by parse_group
            return None
        else:
            # Literal character
            self.pos += 1
            return Literal(ch)

    def parse_char_class(self) -> CharClass:
        """Parse a character class: [abc], [a-z], [^...]"""
        self.pos += 1  # Skip '['
        if self.pos >= self.length:
            raise ValueError("Unclosed character class")

        negated = False
        if self.pattern[self.pos] == '^':
            negated = True
            self.pos += 1

        ranges = []
        while self.pos < self.length and self.pattern[self.pos] != ']':
            start = self.parse_char_class_char()

            if self.pos < self.length - 1 and self.pattern[self.pos] == '-':
                # It's a range
                self.pos += 1  # Skip '-'
                if self.pos >= self.length or self.pattern[self.pos] == ']':
                    # Range at end, treat '-' as literal
                    ranges.append((start, start))
                    ranges.append(('-', '-'))
                    continue
                end = self.parse_char_class_char()
                if ord(start) > ord(end):
                    raise ValueError("Invalid range in character class")
                ranges.append((start, end))
            else:
                # Single character
                ranges.append((start, start))

        if self.pos >= self.length:
            raise ValueError("Unclosed character class")

        self.pos += 1  # Skip ']'
        return CharClass(negated, ranges)

    def parse_char_class_char(self) -> str:
        """Parse a single character inside a character class, handling escapes"""
        if self.pos >= self.length:
            raise ValueError("Unclosed character class")

        ch = self.pattern[self.pos]
        if ch == '\\':
            self.pos += 1
            if self.pos >= self.length:
                raise ValueError("Incomplete escape in character class")
            ch = self.pattern[self.pos]
            self.pos += 1
            return ch
        else:
            self.pos += 1
            return ch

    def parse_group(self) -> Node:
        """Parse a group: (pattern) or alternation (a|b)"""
        self.pos += 1  # Skip '('

        # Parse left side
        left_nodes = []
        while self.pos < self.length and self.pattern[self.pos] != '|' and self.pattern[self.pos] != ')':
            node = self.parse_atom()
            if node is None:
                break
            left_nodes.append(node)

        if self.pos >= self.length:
            raise ValueError("Unclosed group")

        if self.pattern[self.pos] == '|':
            # Alternation
            self.pos += 1  # Skip '|'

            # Parse right side
            right_nodes = []
            while self.pos < self.length and self.pattern[self.pos] != ')':
                node = self.parse_atom()
                if node is None:
                    break
                right_nodes.append(node)

            if self.pos >= self.length:
                raise ValueError("Unclosed group")

            self.pos += 1  # Skip ')'
            return Alternation(left_nodes, right_nodes)
        else:
            # Simple group
            self.pos += 1  # Skip ')'
            return Group(left_nodes)

    def parse_escape(self) -> Node:
        """Parse an escaped character: \., \*, \\, etc."""
        self.pos += 1  # Skip '\\'
        if self.pos >= self.length:
            raise ValueError("Incomplete escape sequence")

        ch = self.pattern[self.pos]
        self.pos += 1

        # Escaped metacharacters become literals
        if ch in '.\\*+?^$[]()|':
            return Literal(ch)
        else:
            # Any other escaped character is just the character itself
            return Literal(ch)

    def apply_quantifier(self, node: Node) -> Node:
        """Apply quantifier (*, +, ?) to the preceding node if present"""
        if self.pos >= self.length:
            return node

        ch = self.pattern[self.pos]
        if ch == '*':
            self.pos += 1
            return Quantifier(node, 0, None)
        elif ch == '+':
            self.pos += 1
            return Quantifier(node, 1, None)
        elif ch == '?':
            self.pos += 1
            return Quantifier(node, 0, 1)
        else:
            return node

    def parse_with_quantifiers(self) -> List[Node]:
        """Parse pattern with quantifiers applied to atoms"""
        nodes = []
        while self.pos < self.length:
            node = self.parse_atom()
            if node is None:
                break

            # Apply quantifier if present
            node = self.apply_quantifier(node)
            nodes.append(node)

        return nodes


class Matcher:
