                return self._match_from(text, text_pos + 1, node_idx + 1)
            return None

        elif isinstance(node, AnyChar):
            if text_pos < len(text):
                return self._match_from(text, text_pos + 1, node_idx + 1)
            return None

        elif isinstance(node, CharClass):
            if text_pos >= len(text):
                return None

            ch = text[text_pos]
            matched = False

            for start, end in node.ranges:
                if start <= ch <= end:
                    matched = True
                    break

            if node.negated:
                matched = not matched

            if matched:
                return self._match_from(text, text_pos + 1, node_idx + 1)
            return None

