from typing import Any, Dict, List, Union

def encode(obj: object) -> str:
    """Serialize object graph to string, preserving shared references and cycles."""
    # Track objects we've seen and their IDs
    obj_to_id: Dict[int, int] = {}
    next_id = 0

    def _encode(obj: Any) -> Any:
        nonlocal next_id

        # Handle None, bool, int, float, str
        if obj is None:
            return {"$type": "null"}
        elif isinstance(obj, bool):
            return {"$type": "bool", "value": obj}
        elif isinstance(obj, int):
            return {"$type": "int", "value": obj}
        elif isinstance(obj, float):
            return {"$type": "float", "value": obj}
        elif isinstance(obj, str):
            return {"$type": "str", "value": obj}

        # For containers (list, dict), check if we've seen this object before
        obj_id = id(obj)
        if obj_id in obj_to_id:
            return {"$type": "ref", "id": obj_to_id[obj_id]}

        # Assign ID to this object
        obj_to_id[obj_id] = next_id
        current_id = next_id
        next_id += 1

        if isinstance(obj, list):
            # Create placeholder first
            result = {"$type": "list", "id": current_id, "items": []}
            # Encode items
            result["items"] = [_encode(item) for item in obj]
            return result
        elif isinstance(obj, dict):
            # Check keys are strings
            for key in obj.keys():
                if not isinstance(key, str):
                    raise ValueError("Dict keys must be strings")
            # Create placeholder first
            result = {"$type": "dict", "id": current_id, "items": {}}
            # Encode items
            result["items"] = {key: _encode(value) for key, value in obj.items()}
            return result
        else:
            raise ValueError(f"Unsupported type: {type(obj)}")

    encoded = _encode(obj)
    return json.dumps(encoded, ensure_ascii=False)

def decode(s: str) -> object:
    """Deserialize string back to object graph, preserving shared references and cycles."""
    try:
        data = json.loads(s)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON input")

    # Track objects by ID for reconstruction
    id_to_obj: Dict[int, Any] = {}

    def _decode(obj_data: Any) -> Any:
        if not isinstance(obj_data, dict) or "$type" not in obj_data:
            raise ValueError("Invalid encoded object")

        obj_type = obj_data["$type"]

        if obj_type == "null":
            return None
        elif obj_type == "bool":
            return bool(obj_data["value"])
        elif obj_type == "int":
            return int(obj_data["value"])
        elif obj_type == "float":
            return float(obj_data["value"])
        elif obj_type == "str":
            return str(obj_data["value"])
        elif obj_type == "ref":
            ref_id = obj_data["id"]
            if ref_id not in id_to_obj:
                raise ValueError(f"Reference to undefined object ID: {ref_id}")
            return id_to_obj[ref_id]
        elif obj_type == "list":
            if "id" not in obj_data or "items" not in obj_data:
                raise ValueError("Invalid list encoding")

            list_id = obj_data["id"]
            # Create empty list as placeholder
            lst = []
            id_to_obj[list_id] = lst

            # Decode items
            items_data = obj_data["items"]
            if not isinstance(items_data, list):
                raise ValueError("Invalid list items encoding")

            lst.extend(_decode(item) for item in items_data)
            return lst
        elif obj_type == "dict":
            if "id" not in obj_data or "items" not in obj_data:
                raise ValueError("Invalid dict encoding")

            dict_id = obj_data["id"]
            # Create empty dict as placeholder
            dct = {}
            id_to_obj[dict_id] = dct

            # Decode items
            items_data = obj_data["items"]
            if not isinstance(items_data, dict):
                raise ValueError("Invalid dict items encoding")

            for key, value_data in items_data.items():
                if not isinstance(key, str):
                    raise ValueError("Dict key must be string")
                dct[key] = _decode(value_data)
            return dct
        else:
            raise ValueError(f"Unknown type: {obj_type}")

    return _decode(data)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def __init__(self):
        self.root = None

    def _height(self, node):
        return node.height if node else 0

    def _update_height(self, node):
        if node:
            node.height = 1 + max(self._height(node.left), self._height(node.right))

    def _balance_factor(self, node):
        if not node:
            return 0
        return self._height(node.left) - self._height(node.right)

    def _rotate_right(self, y):
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        self._update_height(y)
        self._update_height(x)

        return x

    def _rotate_left(self, x):
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        self._update_height(x)
        self._update_height(y)

        return y

    def _rebalance(self, node):
        if not node:
            return node

        self._update_height(node)
        balance = self._balance_factor(node)

        # Left heavy
        if balance > 1:
            # Left-Right case
            if self._balance_factor(node.left) < 0:
                node.left = self._rotate_left(node.left)
            # Left-Left case
            return self._rotate_right(node)

        # Right heavy
        if balance < -1:
            # Right-Left case
            if self._balance_factor(node.right) > 0:
                node.right = self._rotate_right(node.right)
            # Right-Right case
            return self._rotate_left(node)

        return node

    def _insert_node(self, node, key):
        if not node:
            return Node(key)

        if key < node.val:
            node.left = self._insert_node(node.left, key)
        elif key > node.val:
            node.right = self._insert_node(node.right, key)
        else:
            # Duplicate - no-op
            return node

        return self._rebalance(node)

    def insert(self, key: int) -> None:
        self.root = self._insert_node(self.root, key)

    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def _delete_node(self, node, key):
        if not node:
            return node

        if key < node.val:
            node.left = self._delete_node(node.left, key)
        elif key > node.val:
            node.right = self._delete_node(node.right, key)
        else:
            # Node found
            if not node.left:
                return node.right
            elif not node.right:
                return node.left
            else:
                # Node with two children
                temp = self._min_value_node(node.right)
                node.val = temp.val
                node.right = self._delete_node(node.right, temp.val)

        return self._rebalance(node)

    def delete(self, key: int) -> None:
        self.root = self._delete_node(self.root, key)

    def _contains_node(self, node, key):
        if not node:
            return False
        if key == node.val:
            return True
        elif key < node.val:
            return self._contains_node(node.left, key)
        else:
            return self._contains_node(node.right, key)

    def contains(self, key: int) -> bool:
        return self._contains_node(self.root, key)

def evaluate(expr: str) -> float:
    # Tokenization
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        # Number: digit sequence with optional decimal point
        if ch.isdigit() or ch == '.':
            # Validate: digit must precede decimal point
            start = i
            has_digit = False
            has_dot = False
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    if has_dot:
                        # Multiple dots invalid
                        raise ValueError("Invalid number")
                    has_dot = True
                else:
                    has_digit = True
                i += 1
            # Check digit before decimal
            if has_dot and not has_digit:
                raise ValueError("Invalid number: digit must precede decimal point")
            if not has_digit:
                raise ValueError("Invalid number")
            num_str = expr[start:i]
            tokens.append(float(num_str))
            continue
        # Operators and parentheses
        if ch in '+-*/%()':
            tokens.append(ch)
            i += 1
            continue
        # Exponentiation operator **
        if ch == '*':
            if i + 1 < n and expr[i + 1] == '*':
                tokens.append('**')
                i += 2
                continue
            tokens.append('*')
            i += 1
            continue
        # Invalid character
        raise ValueError(f"Invalid token '{ch}'")

    # Convert infix to RPN using shunting-yard
    output = []
    stack = []

    # Helper to determine if token is operator
    def is_operator(tok):
        return tok in ('+', '-', '*', '/', '%', '**')

    # Precedence: higher number = higher precedence
    precedence = {
        '**': 4,
        'u+': 3,  # unary plus
        'u-': 3,  # unary minus
        '*': 2,
        '/': 2,
        '%': 2,
        '+': 1,
        '-': 1,
    }

    # Determine if '-' or '+' is unary
    def handle_unary(i):
        # Check if token at position i is a unary + or -
        if tokens[i] not in ('+', '-'):
            return tokens[i]
        # Unary if:
        # 1. First token
        if i == 0:
            return 'u' + tokens[i]
        # 2. Previous token is '(' or operator (including **)
        prev = tokens[i - 1]
        if prev == '(' or (is_operator(prev) and prev != ')'):
            return 'u' + tokens[i]
        # 3. Previous token is unary operator (should not happen due to detection)
        return tokens[i]

    # Process tokens
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        # Handle unary +/-
        if tok in ('+', '-'):
            tok = handle_unary(i)

        if isinstance(tok, float):
            output.append(tok)
        elif tok == '(':
            stack.append(tok)
        elif tok == ')':
            # Pop until '('
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if not stack or stack[-1] != '(':
                raise ValueError("Mismatched parentheses")
            stack.pop()  # discard '('
        elif is_operator(tok) or tok in ('u+', 'u-'):
            # Right-associative: **
            # Left-associative: others
            while stack and stack[-1] != '(':
                top = stack[-1]
                if (precedence.get(top, 0) > precedence.get(tok, 0) or
                    (precedence.get(top, 0) == precedence.get(tok, 0) and
                     tok != '**')):  # left-associative except **
                    output.append(stack.pop())
                else:
                    break
            stack.append(tok)
        i += 1

    # Pop remaining operators
    while stack:
        if stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(stack.pop())

    # Evaluate RPN
    eval_stack = []
    for token in output:
        if isinstance(token, float):
            eval_stack.append(token)
        elif token in ('u+', 'u-'):
            if len(eval_stack) < 1:
                raise ValueError("Invalid expression")
            a = eval_stack.pop()
            if token == 'u+':
                eval_stack.append(a)
            else:  # 'u-'
                eval_stack.append(-a)
        else:
            # Binary operator
            if len(eval_stack) < 2:
                raise ValueError("Invalid expression")
            b = eval_stack.pop()
            a = eval_stack.pop()
            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                eval_stack.append(a / b)
            elif token == '%':
                if b == 0:
                    raise ValueError("Modulo by zero")
                # Python's % with floats
                eval_stack.append(a % b)
            elif token == '**':
                eval_stack.append(a ** b)
            else:
                raise ValueError(f"Unknown operator {token}")

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    return float(eval_stack[0])

def critical_path(durations: dict, deps: list) -> tuple:
    # Handle empty durations
    if not durations:
        return (0.0, [])

    # Build adjacency list and indegree/outdegree counts
    adj = {task: [] for task in durations}
    indegree = {task: 0 for task in durations}
    outdegree = {task: 0 for task in durations}

    for a, b in deps:
        if a not in adj:
            adj[a] = []
        if b not in adj:
            adj[b] = []
        adj[a].append(b)
        indegree[b] += 1
        outdegree[a] += 1

    # Initialize all tasks
    tasks = list(durations.keys())

    # Topological sort with cycle detection
    indegree_copy = indegree.copy()
    queue = [task for task in tasks if indegree_copy[task] == 0]
    topo_order = []

    while queue:
        task = queue.pop(0)
        topo_order.append(task)
        for neighbor in adj.get(task, []):
            indegree_copy[neighbor] -= 1
            if indegree_copy[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycle
    if len(topo_order) != len(tasks):
        raise ValueError("Cycle detected")

    # Forward pass: compute earliest start times
    earliest_start = {task: 0.0 for task in tasks}
    for task in topo_order:
        for neighbor in adj.get(task, []):
            earliest_start[neighbor] = max(
                earliest_start[neighbor],
                earliest_start[task] + durations[task]
            )

    # Project duration is max of earliest finish times
    project_duration = max(
        earliest_start[task] + durations[task] for task in tasks
    )

    # Backward pass: compute latest start times
    latest_start = {task: float('inf') for task in tasks}
    # Initialize sink tasks (no outgoing edges)
    for task in tasks:
        if outdegree[task] == 0:
            latest_start[task] = project_duration - durations[task]

    # Process in reverse topological order
    for task in reversed(topo_order):
        # Update predecessors
        for pred in tasks:
            if task in adj.get(pred, []):
                latest_start[pred] = min(
                    latest_start[pred],
                    latest_start[task] - durations[pred]
                )

    # Find critical path: tasks where earliest_start == latest_start
    # and form a continuous path from source to sink
    critical_tasks = {
        task for task in tasks 
        if abs(earliest_start[task] - latest_start[task]) < 1e-9
    }

    # Build the critical path from source to sink
    # Find source critical tasks (indegree 0 or all predecessors not critical)
    source_critical = []
    for task in critical_tasks:
        is_source = True
        for pred in tasks:
            if task in adj.get(pred, []) and pred in critical_tasks:
                is_source = False
                break
        if is_source:
            source_critical.append(task)

    # Start from a source critical task and follow critical successors
    if not source_critical:
        # If no obvious source, start from any critical task
        # that has earliest_start = 0
        for task in critical_tasks:
            if abs(earliest_start[task]) < 1e-9:
                source_critical.append(task)
                break

    if not source_critical:
        # Fallback: use first critical task
        source_critical.append(next(iter(critical_tasks)))

    # Build path from source to sink
    path = []
    current = source_critical[0]
    visited = set()

    while current and current not in visited:
        visited.add(current)
        path.append(current)

        # Find critical successor
        next_task = None
        for neighbor in adj.get(current, []):
            if neighbor in critical_tasks:
                next_task = neighbor
                break

        current = next_task

    # Verify path sum equals project duration
    path_duration = sum(durations[task] for task in path)
    if abs(path_duration - project_duration) > 1e-9:
        # If path doesn't match, try to find a better path
        # by exploring all possible critical paths
        def dfs_find_path(current, current_path, current_sum):
            if outdegree[current] == 0:
                if abs(current_sum - project_duration) < 1e-9:
                    return current_path
                return None

            for neighbor in adj.get(current, []):
                if neighbor in critical_tasks:
                    result = dfs_find_path(
                        neighbor, 
                        current_path + [neighbor],
                        current_sum + durations[neighbor]
                    )
                    if result:
                        return result
            return None

        # Try from each source critical task
        for source in source_critical:
            result = dfs_find_path(source, [source], durations[source])
            if result:
                path = result
                break

    return (project_duration, path)

def brainfuck(code: str, input_str: str = "") -> str:
    # Initialize tape with 30,000 cells
    tape = [0] * 30000
    pointer = 0
    input_index = -1  # Start before first character
    output = []

    # Preprocess to find matching brackets
    stack = []
    bracket_map = {}

    # First pass: build bracket map and check for unbalanced brackets
    for i, char in enumerate(code):
        if char == '[':
            stack.append(i)
        elif char == ']':
            if not stack:
                raise ValueError("Unbalanced brackets")
            open_idx = stack.pop()
            bracket_map[open_idx] = i
            bracket_map[i] = open_idx

    # If stack not empty after processing, brackets are unbalanced
    if stack:
        raise ValueError("Unbalanced brackets")

    # Execute the code
    i = 0
    while i < len(code):
        char = code[i]

        if char == '>':
            pointer += 1
            if pointer >= 30000:
                pointer = 29999  # Stay within bounds
        elif char == '<':
            pointer -= 1
            if pointer < 0:
                pointer = 0  # Stay within bounds
        elif char == '+':
            tape[pointer] += 1
            # No wraparound - just keep incrementing
        elif char == '-':
            tape[pointer] -= 1
            # No wraparound - just keep decrementing
        elif char == '.':
            output.append(chr(tape[pointer]))
        elif char == ',':
            input_index += 1
            if input_index < len(input_str):
                tape[pointer] = ord(input_str[input_index])
            else:
                tape[pointer] = 0  # EOF -> 0
        elif char == '[':
            if tape[pointer] == 0:
                # Jump forward to matching ']'
                i = bracket_map[i]
        elif char == ']':
            if tape[pointer] != 0:
                # Jump back to matching '['
                i = bracket_map[i]
        # Other characters are ignored

        i += 1

    return ''.join(output)

import re
from typing import Union, Dict, List

def parse_json(text: str) -> Union[Dict, List, str, int, float, bool, None]:
    """
    Parse a JSON string and return the Python equivalent.
    Raises ValueError on invalid input.
    """
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    # Parse the JSON value and check for trailing content
    result, idx = _parse_value(text, 0)

    # Check for trailing content
    idx = _skip_whitespace(text, idx)
    if idx != len(text):
        raise ValueError("Trailing content after JSON value")

    return result


def _skip_whitespace(text: str, idx: int) -> int:
    """Skip whitespace characters."""
    while idx < len(text) and text[idx] in ' \t\n\r':
        idx += 1
    return idx


def _parse_value(text: str, idx: int) -> tuple:
    """Parse a JSON value starting at idx."""
    idx = _skip_whitespace(text, idx)

    if idx >= len(text):
        raise ValueError("Unexpected end of input")

    ch = text[idx]

    if ch == '{':
        return _parse_object(text, idx)
    elif ch == '[':
        return _parse_array(text, idx)
    elif ch == '"':
        return _parse_string(text, idx)
    elif ch == 't':
        return _parse_true(text, idx)
    elif ch == 'f':
        return _parse_false(text, idx)
    elif ch == 'n':
        return _parse_null(text, idx)
    elif ch == '-' or ch.isdigit():
        return _parse_number(text, idx)
    else:
        raise ValueError(f"Unexpected character '{ch}' at position {idx}")


def _parse_object(text: str, idx: int) -> tuple:
    """Parse a JSON object."""
    if text[idx] != '{':
        raise ValueError(f"Expected '{{' at position {idx}")

    idx += 1
    idx = _skip_whitespace(text, idx)
    obj = {}

    if idx < len(text) and text[idx] == '}':
        # Empty object
        return obj, idx + 1

    first = True
    while True:
        if not first:
            idx = _skip_whitespace(text, idx)
            if idx >= len(text):
                raise ValueError("Unclosed object")
            if text[idx] != ',':
                break
            idx += 1
            idx = _skip_whitespace(text, idx)

        # Parse key
        if idx >= len(text) or text[idx] != '"':
            raise ValueError(f"Expected string key at position {idx}")
        key, idx = _parse_string(text, idx)

        # Parse colon
        idx = _skip_whitespace(text, idx)
        if idx >= len(text) or text[idx] != ':':
            raise ValueError(f"Expected ':' at position {idx}")
        idx += 1

        # Parse value
        value, idx = _parse_value(text, idx)
        obj[key] = value

        first = False

    idx = _skip_whitespace(text, idx)
    if idx >= len(text) or text[idx] != '}':
        raise ValueError("Unclosed object")

    return obj, idx + 1


def _parse_array(text: str, idx: int) -> tuple:
    """Parse a JSON array."""
    if text[idx] != '[':
        raise ValueError(f"Expected '[' at position {idx}")

    idx += 1
    idx = _skip_whitespace(text, idx)
    arr = []

    if idx < len(text) and text[idx] == ']':
        # Empty array
        return arr, idx + 1

    first = True
    while True:
        if not first:
            idx = _skip_whitespace(text, idx)
            if idx >= len(text):
                raise ValueError("Unclosed array")
            if text[idx] != ',':
                break
            idx += 1
            idx = _skip_whitespace(text, idx)

        # Parse value
        value, idx = _parse_value(text, idx)
        arr.append(value)

        first = False

    idx = _skip_whitespace(text, idx)
    if idx >= len(text) or text[idx] != ']':
        raise ValueError("Unclosed array")

    return arr, idx + 1


def _parse_string(text: str, idx: int) -> tuple:
    """Parse a JSON string."""
    if text[idx] != '"':
        raise ValueError(f"Expected '\"' at position {idx}")

    idx += 1
    start = idx
    result = []

    while idx < len(text):
        ch = text[idx]

        if ch == '"':
            # End of string
            if start < idx:
                result.append(text[start:idx])
            idx += 1
            return ''.join(result), idx

        elif ch == '\\':
            # Escape sequence
            if start < idx:
                result.append(text[start:idx])

            idx += 1
            if idx >= len(text):
                raise ValueError("Unterminated escape sequence")

            esc = text[idx]
            idx += 1

            if esc == '"':
                result.append('"')
            elif esc == '\\':
                result.append('\\')
            elif esc == '/':
                result.append('/')
            elif esc == 'b':
                result.append('\b')
            elif esc == 'f':
                result.append('\f')
            elif esc == 'n':
                result.append('\n')
            elif esc == 'r':
                result.append('\r')
            elif esc == 't':
                result.append('\t')
            elif esc == 'u':
                # Unicode escape
                if idx + 4 > len(text):
                    raise ValueError("Incomplete Unicode escape")

                hex_str = text[idx:idx+4]
                if not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                    raise ValueError(f"Invalid Unicode escape: \\u{hex_str}")

                code_point = int(hex_str, 16)
                result.append(chr(code_point))
                idx += 4
            else:
                raise ValueError(f"Invalid escape sequence: \\{esc}")

            start = idx

        elif ord(ch) < 0x20:
            # Control characters (except whitespace which we skip earlier)
            raise ValueError(f"Control character in string at position {idx}")

        else:
            idx += 1

    raise ValueError("Unclosed string")


def _parse_true(text: str, idx: int) -> tuple:
    """Parse 'true' literal."""
    if text[idx:idx+4] == 'true':
        return True, idx + 4
    raise ValueError(f"Expected 'true' at position {idx}")


def _parse_false(text: str, idx: int) -> tuple:
    """Parse 'false' literal."""
    if text[idx:idx+5] == 'false':
        return False, idx + 5
    raise ValueError(f"Expected 'false' at position {idx}")


def _parse_null(text: str, idx: int) -> tuple:
    """Parse 'null' literal."""
    if text[idx:idx+4] == 'null':
        return None, idx + 4
    raise ValueError(f"Expected 'null' at position {idx}")


def _parse_number(text: str, idx: int) -> tuple:
    """Parse a JSON number."""
    start = idx

    # Check for leading zero
    if text[idx] == '0' and idx + 1 < len(text) and text[idx+1].isdigit():
        raise ValueError("Numbers cannot have leading zeros")

    # Optional minus sign
    if text[idx] == '-':
        idx += 1
        if idx >= len(text):
            raise ValueError("Incomplete number")

    # Integer part
    if idx < len(text) and text[idx] == '0':
        idx += 1
    elif idx < len(text) and text[idx].isdigit():
        while idx < len(text) and text[idx].isdigit():
            idx += 1
    else:
        raise ValueError(f"Expected digit at position {idx}")

    # Fraction part
    if idx < len(text) and text[idx] == '.':
        idx += 1
        if idx >= len(text) or not text[idx].isdigit():
            raise ValueError("Expected digit after decimal point")

        while idx < len(text) and text[idx].isdigit():
            idx += 1

    # Exponent part
    if idx < len(text) and text[idx] in 'eE':
        idx += 1
        if idx >= len(text):
            raise ValueError("Incomplete exponent")

        if text[idx] in '+-':
            idx += 1

        if idx >= len(text) or not text[idx].isdigit():
            raise ValueError("Expected digit in exponent")

        while idx < len(text) and text[idx].isdigit():
            idx += 1

    # Parse the number
    num_str = text[start:idx]

    # Check for invalid formats
    if num_str.startswith('+'):
        raise ValueError("Numbers cannot start with '+'")

    if num_str.endswith('.'):
        raise ValueError("Numbers cannot end with decimal point")

    # Parse as float if it has exponent or decimal point
    if 'e' in num_str.lower() or '.' in num_str:
        try:
            return float(num_str), idx
        except ValueError:
            raise ValueError(f"Invalid number format: {num_str}")
    else:
        # Integer
        try:
            return int(num_str), idx
        except ValueError:
            raise ValueError(f"Invalid number format: {num_str}")

def encode(obj: object) -> str:
    """
    Serialize a Python object graph to a string, preserving shared references and cycles.
    Supported types: int, float, bool, None, str, list, dict (string keys only).
    """
    # First pass: assign IDs to all objects
    obj_to_id = {}
    next_id = 0
    stack = [obj]

    # BFS to assign IDs to all objects
    while stack:
        current = stack.pop()
        if id(current) in obj_to_id:
            continue

        obj_to_id[id(current)] = next_id
        next_id += 1

        if isinstance(current, dict):
            for key, value in current.items():
                if not isinstance(key, str):
                    raise ValueError(f"Unsupported dict key type: {type(key)}")
                if isinstance(value, (list, dict)):
                    stack.append(value)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (list, dict)):
                    stack.append(item)

    # Second pass: serialize with references
    result_parts = []

    def serialize(obj_ref):
        obj_id = obj_to_id[id(obj_ref)]

        if isinstance(obj_ref, (int, float, bool, type(None), str)):
            # Primitive types
            if isinstance(obj_ref, int):
                return f"i:{obj_ref}:{obj_id}"
            elif isinstance(obj_ref, float):
                return f"f:{obj_ref}:{obj_id}"
            elif isinstance(obj_ref, bool):
                return f"b:{int(obj_ref)}:{obj_id}"
            elif obj_ref is None:
                return f"n::{obj_id}"
            elif isinstance(obj_ref, str):
                # Escape colons and backslashes
                escaped = obj_ref.replace('\\', '\\\\').replace(':', '\\:')
                return f"s:{escaped}:{obj_id}"

        elif isinstance(obj_ref, list):
            # List - serialize contents
            item_refs = []
            for item in obj_ref:
                if isinstance(item, (int, float, bool, type(None), str)):
                    # Primitive - serialize inline
                    if isinstance(item, int):
                        item_refs.append(f"i:{item}")
                    elif isinstance(item, float):
                        item_refs.append(f"f:{item}")
                    elif isinstance(item, bool):
                        item_refs.append(f"b:{int(item)}")
                    elif item is None:
                        item_refs.append("n:")
                    elif isinstance(item, str):
                        escaped = item.replace('\\', '\\\\').replace(':', '\\:')
                        item_refs.append(f"s:{escaped}")
                else:
                    # Complex - reference by ID
                    item_refs.append(f"r:{obj_to_id[id(item)]}")

            return f"l:{','.join(item_refs)}:{obj_id}"

        elif isinstance(obj_ref, dict):
            # Dict - serialize key-value pairs
            pairs = []
            for key, value in obj_ref.items():
                # Key is always a string
                escaped_key = key.replace('\\', '\\\\').replace(':', '\\:')

                if isinstance(value, (int, float, bool, type(None), str)):
                    # Primitive value
                    if isinstance(value, int):
                        pairs.append(f"{escaped_key}:i:{value}")
                    elif isinstance(value, float):
                        pairs.append(f"{escaped_key}:f:{value}")
                    elif isinstance(value, bool):
                        pairs.append(f"{escaped_key}:b:{int(value)}")
                    elif value is None:
                        pairs.append(f"{escaped_key}:n:")
                    elif isinstance(value, str):
                        escaped_val = value.replace('\\', '\\\\').replace(':', '\\:')
                        pairs.append(f"{escaped_key}:s:{escaped_val}")
                else:
                    # Complex value - reference by ID
                    pairs.append(f"{escaped_key}:r:{obj_to_id[id(value)]}")

            return f"d:{','.join(pairs)}:{obj_id}"

        else:
            raise ValueError(f"Unsupported type: {type(obj_ref)}")

    # Serialize all objects
    serialized = {}
    for obj_id, obj_ptr in enumerate(obj_to_id.keys()):
        # Find the object with this ID
        for ptr, oid in obj_to_id.items():
            if oid == obj_id:
                obj_ref = None
                # We need to find the actual object
                # Since we only stored IDs, we need to track back to the original
                # Let's do another traversal
                def find_obj(current_obj, target_id):
                    if obj_to_id[id(current_obj)] == target_id:
                        return current_obj

                    if isinstance(current_obj, dict):
                        for k, v in current_obj.items():
                            if isinstance(v, (list, dict)):
                                result = find_obj(v, target_id)
                                if result is not None:
                                    return result
                    elif isinstance(current_obj, list):
                        for item in current_obj:
                            if isinstance(item, (list, dict)):
                                result = find_obj(item, target_id)
                                if result is not None:
                                    return result
                    return None

                obj_ref = find_obj(obj, obj_id)
                if obj_ref is not None:
                    serialized[obj_id] = serialize(obj_ref)
                break

    # Build final string: all objects separated by '|'
    return '|'.join(serialized[oid] for oid in range(len(serialized)))


def decode(s: str) -> object:
    """
    Deserialize a string back to a Python object graph, preserving shared references and cycles.
    """
    if not s:
        raise ValueError("Empty input string")

    parts = s.split('|')
    objects = {}  # id -> object
    unresolved_refs = []  # (obj_id, key_or_index, ref_id)

    # First pass: create skeleton objects
    for part in parts:
        if not part:
            continue

        # Parse the object
        if part.startswith('i:'):
            # int
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid int format: {part}")
            value_str, id_str = rest.rsplit(':', 1)
            try:
                value = int(value_str)
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid int format: {part}")
            objects[obj_id] = value

        elif part.startswith('f:'):
            # float
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid float format: {part}")
            value_str, id_str = rest.rsplit(':', 1)
            try:
                value = float(value_str)
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid float format: {part}")
            objects[obj_id] = value

        elif part.startswith('b:'):
            # bool
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid bool format: {part}")
            value_str, id_str = rest.rsplit(':', 1)
            try:
                value = bool(int(value_str))
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid bool format: {part}")
            objects[obj_id] = value

        elif part.startswith('n:'):
            # None
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid None format: {part}")
            _, id_str = rest.rsplit(':', 1)
            try:
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid None format: {part}")
            objects[obj_id] = None

        elif part.startswith('s:'):
            # string
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid string format: {part}")
            # Need to handle escaped colons
            escaped_str, id_str = rest.rsplit(':', 1)
            # Unescape
            value = escaped_str.replace('\\:', ':').replace('\\\\', '\\')
            try:
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid string format: {part}")
            objects[obj_id] = value

        elif part.startswith('l:'):
            # list
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid list format: {part}")
            items_str, id_str = rest.rsplit(':', 1)
            try:
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid list format: {part}")

            # Create empty list
            lst = []
            objects[obj_id] = lst

            if items_str:
                item_parts = items_str.split(',')
                for i, item_part in enumerate(item_parts):
                    if item_part.startswith('i:'):
                        value = int(item_part[2:])
                        lst.append(value)
                    elif item_part.startswith('f:'):
                        value = float(item_part[2:])
                        lst.append(value)
                    elif item_part.startswith('b:'):
                        value = bool(int(item_part[2:]))
                        lst.append(value)
                    elif item_part == 'n:':
                        lst.append(None)
                    elif item_part.startswith('s:'):
                        escaped = item_part[2:]
                        value = escaped.replace('\\:', ':').replace('\\\\', '\\')
                        lst.append(value)
                    elif item_part.startswith('r:'):
                        ref_id = int(item_part[2:])
                        unresolved_refs.append((obj_id, i, ref_id))
                    else:
                        raise ValueError(f"Invalid list item format: {item_part}")

        elif part.startswith('d:'):
            # dict
            rest = part[2:]
            if ':' not in rest:
                raise ValueError(f"Invalid dict format: {part}")
            pairs_str, id_str = rest.rsplit(':', 1)
            try:
                obj_id = int(id_str)
            except ValueError:
                raise ValueError(f"Invalid dict format: {part}")

            # Create empty dict
            dct = {}
            objects[obj_id] = dct

            if pairs_str:
                pair_parts = pairs_str.split(',')
                for pair in pair_parts:
                    # Key is always a string, may contain escaped colons
                    # Find the first unescaped colon after the key
                    i = 0
                    while i < len(pair):
                        if pair[i] == '\\':
                            i += 2  # Skip escaped character
                        elif pair[i] == ':':
                            break
                        else:
                            i += 1

                    if i >= len(pair):
                        raise ValueError(f"Invalid dict pair format: {pair}")

                    key_escaped = pair[:i]
                    rest = pair[i+1:]

                    # Unescape key
                    key = key_escaped.replace('\\:', ':').replace('\\\\', '\\')

                    if rest.startswith('i:'):
                        value = int(rest[2:])
                        dct[key] = value
                    elif rest.startswith('f:'):
                        value = float(rest[2:])
                        dct[key] = value
                    elif rest.startswith('b:'):
                        value = bool(int(rest[2:]))
                        dct[key] = value
                    elif rest == 'n:':
                        dct[key] = None
                    elif rest.startswith('s:'):
                        escaped = rest[2:]
                        value = escaped.replace('\\:', ':').replace('\\\\', '\\')
                        dct[key] = value
                    elif rest.startswith('r:'):
                        ref_id = int(rest[2:])
                        unresolved_refs.append((obj_id, key, ref_id))
                    else:
                        raise ValueError(f"Invalid dict value format: {rest}")

        else:
            raise ValueError(f"Unknown object type prefix: {part}")

    # Second pass: resolve references
    for obj_id, key_or_index, ref_id in unresolved_refs:
        if ref_id not in objects:
            raise ValueError(f"Reference to non-existent object ID: {ref_id}")

        obj = objects[obj_id]
        if isinstance(key_or_index, int):  # list index
            obj[key_or_index] = objects[ref_id]
        else:  # dict key
            obj[key_or_index] = objects[ref_id]

    # Return the root object (ID 0)
    if 0 not in objects:
        raise ValueError("No root object (ID 0) found")

    return objects[0]

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.height = 1


class AVLTree:
    def __init__(self):
        self.root = None

    def insert(self, key: int) -> None:
        self.root = self._insert(self.root, key)

    def delete(self, key: int) -> None:
        self.root = self._delete(self.root, key)

    def contains(self, key: int) -> bool:
        return self._contains(self.root, key)

    # Helper methods
    def _height(self, node):
        return node.height if node else 0

    def _update_height(self, node):
        if node:
            node.height = 1 + max(self._height(node.left), self._height(node.right))

    def _balance_factor(self, node):
        if not node:
            return 0
        return self._height(node.left) - self._height(node.right)

    def _rotate_right(self, y):
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        self._update_height(y)
        self._update_height(x)

        return x

    def _rotate_left(self, x):
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        self._update_height(x)
        self._update_height(y)

        return y

    def _rebalance(self, node):
        if not node:
            return node

        self._update_height(node)
        balance = self._balance_factor(node)

        # Left heavy
        if balance > 1:
            # Left-Right case
            if self._balance_factor(node.left) < 0:
                node.left = self._rotate_left(node.left)
            return self._rotate_right(node)

        # Right heavy
        if balance < -1:
            # Right-Left case
            if self._balance_factor(node.right) > 0:
                node.right = self._rotate_right(node.right)
            return self._rotate_left(node)

        return node

    def _insert(self, node, key):
        if not node:
            return Node(key)

        if key < node.val:
            node.left = self._insert(node.left, key)
        elif key > node.val:
            node.right = self._insert(node.right, key)
        else:
            # Duplicate key, no-op
            return node

        return self._rebalance(node)

    def _contains(self, node, key):
        if not node:
            return False
        if key == node.val:
            return True
        elif key < node.val:
            return self._contains(node.left, key)
        else:
            return self._contains(node.right, key)

    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def _delete(self, node, key):
        if not node:
            return None

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            # Node to delete found
            # Node with only one child or no child
            if not node.left:
                return node.right
            elif not node.right:
                return node.left
            else:
                # Node with two children
                temp = self._min_value_node(node.right)
                node.val = temp.val
                node.right = self._delete(node.right, temp.val)

        return self._rebalance(node)

import operator
import math

def evaluate(expr: str) -> float:
    """Evaluate an infix arithmetic expression and return the numeric result as a float."""

    # Remove whitespace
    expr = expr.strip()
    if not expr:
        raise ValueError("Empty expression")

    # Operator precedence and associativity
    # Higher number = higher precedence
    PRECEDENCE = {
        '**': 4,
        'u+': 3,  # unary plus
        'u-': 3,  # unary minus
        '*': 2,
        '/': 2,
        '%': 2,
        '+': 1,
        '-': 1,
    }

    # Right-associative operators
    RIGHT_ASSOC = {'**', 'u+', 'u-'}

    # Operator functions
    OPERATORS = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '%': operator.mod,
        '**': operator.pow,
        'u+': lambda x: x,
        'u-': lambda x: -x,
    }

    def is_digit(ch: str) -> bool:
        return ch.isdigit()

    def is_number_start(ch: str) -> bool:
        return ch.isdigit() or ch == '.'

    def tokenize(expression: str):
        """Tokenize the expression into numbers, operators, and parentheses."""
        i = 0
        n = len(expression)
        tokens = []

        while i < n:
            ch = expression[i]

            # Skip whitespace
            if ch.isspace():
                i += 1
                continue

            # Number (integer or decimal)
            if is_number_start(ch):
                start = i
                dot_seen = False
                while i < n and (is_digit(expression[i]) or expression[i] == '.'):
                    if expression[i] == '.':
                        if dot_seen:
                            raise ValueError("Invalid number with multiple decimal points")
                        dot_seen = True
                    i += 1

                # Check if number ends with decimal point
                if expression[i-1] == '.':
                    raise ValueError("Invalid number ending with decimal point")

                num_str = expression[start:i]
                # Must have at least one digit before decimal point
                if num_str.startswith('.'):
                    raise ValueError("Number must have digit before decimal point")

                try:
                    tokens.append(float(num_str))
                except ValueError:
                    raise ValueError(f"Invalid number: {num_str}")
                continue

            # Parentheses
            if ch in '()':
                tokens.append(ch)
                i += 1
                continue

            # Operators
            if ch in '+-*/%':
                # Check for exponentiation operator '**'
                if ch == '*' and i + 1 < n and expression[i+1] == '*':
                    tokens.append('**')
                    i += 2
                    continue
                else:
                    tokens.append(ch)
                    i += 1
                    continue

            # Invalid character
            raise ValueError(f"Invalid character: {ch}")

        return tokens

    # Tokenize the expression
    try:
        tokens = tokenize(expr)
    except ValueError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Convert to RPN using shunting-yard algorithm
    output = []
    stack = []

    # Helper to determine if a token is a unary operator
    def is_unary_operator(pos, token):
        """Determine if + or - is unary at position pos."""
        if token not in ('+', '-'):
            return False

        # At start of expression
        if pos == 0:
            return True

        # After '('
        if tokens[pos-1] == '(':
            return True

        # After another operator (including '**')
        if pos > 0 and isinstance(tokens[pos-1], str) and tokens[pos-1] not in ')':
            # Check if previous token is an operator (not a number or ')')
            # This includes all operators: '+', '-', '*', '/', '%', '**'
            return True

        return False

    i = 0
    while i < len(tokens):
        token = tokens[i]

        # Number
        if isinstance(token, (int, float)):
            output.append(token)

        # Function or operator
        elif isinstance(token, str):
            if token == '(':
                stack.append(token)

            elif token == ')':
                # Pop until '(' is found
                while stack and stack[-1] != '(':
                    output.append(stack.pop())

                if not stack:
                    raise ValueError("Mismatched parentheses")

                # Remove '('
                stack.pop()

            else:
                # Handle unary + and -
                if token in ('+', '-') and is_unary_operator(i, token):
                    # Convert to unary operator token
                    token = 'u+' if token == '+' else 'u-'

                # While there's an operator at the top of the stack with greater precedence
                # or equal precedence and left-associative
                while stack and stack[-1] != '(' and stack[-1] in PRECEDENCE:
                    top_op = stack[-1]

                    # Compare precedence
                    if (PRECEDENCE[top_op] > PRECEDENCE[token] or
                        (PRECEDENCE[top_op] == PRECEDENCE[token] and 
                         token not in RIGHT_ASSOC)):
                        output.append(stack.pop())
                    else:
                        break

                stack.append(token)

        i += 1

    # Pop remaining operators from stack
    while stack:
        op = stack.pop()
        if op == '(':
            raise ValueError("Mismatched parentheses")
        output.append(op)

    # Evaluate RPN
    eval_stack = []

    for token in output:
        if isinstance(token, (int, float)):
            eval_stack.append(token)
        else:
            # Operator
            if token in ('u+', 'u-'):
                # Unary operator
                if not eval_stack:
                    raise ValueError("Invalid expression: missing operand")
                a = eval_stack.pop()
                result = OPERATORS[token](a)
                eval_stack.append(result)
            else:
                # Binary operator
                if len(eval_stack) < 2:
                    raise ValueError("Invalid expression: insufficient operands")
                b = eval_stack.pop()
                a = eval_stack.pop()

                # Check for division by zero
                if token == '/' and b == 0:
                    raise ValueError("Division by zero")
                if token == '%' and b == 0:
                    raise ValueError("Modulo by zero")

                result = OPERATORS[token](a, b)
                eval_stack.append(result)

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    return float(eval_stack[0])

def critical_path(durations: dict, deps: list) -> tuple:
    # Empty durations case
    if not durations:
        return (0.0, [])

    # Validate all tasks in dependencies exist in durations
    all_tasks = set(durations.keys())
    for a, b in deps:
        if a not in all_tasks:
            raise ValueError(f"Task {a} in dependencies not found in durations")
        if b not in all_tasks:
            raise ValueError(f"Task {b} in dependencies not found in durations")

    # Build adjacency list and indegree count
    adj = {task: [] for task in all_tasks}
    indegree = {task: 0 for task in all_tasks}
    for a, b in deps:
        adj[a].append(b)
        indegree[b] += 1

    # Topological sort (Kahn's algorithm) for cycle detection
    zero_indegree = [task for task in all_tasks if indegree[task] == 0]
    topo_order = []

    while zero_indegree:
        task = zero_indegree.pop()
        topo_order.append(task)
        for neighbor in adj[task]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                zero_indegree.append(neighbor)

    # If not all tasks were processed, there's a cycle
    if len(topo_order) != len(all_tasks):
        raise ValueError("Dependency graph contains a cycle")

    # Forward pass: compute earliest start times
    earliest_start = {task: 0.0 for task in all_tasks}
    for task in topo_order:
        for neighbor in adj[task]:
            earliest_start[neighbor] = max(
                earliest_start[neighbor],
                earliest_start[task] + durations[task]
            )

    # Project duration is max of earliest_start + duration
    project_duration = 0.0
    for task in all_tasks:
        project_duration = max(
            project_duration,
            earliest_start[task] + durations[task]
        )

    # Backward pass: compute latest start times
    latest_start = {task: float('inf') for task in all_tasks}
    # Initialize sinks (tasks with no outgoing edges)
    for task in all_tasks:
        if not adj[task]:  # sink task
            latest_start[task] = project_duration - durations[task]

    # Process in reverse topological order
    for task in reversed(topo_order):
        # For each predecessor (we need reverse adjacency)
        # But we can compute from successors since we have forward adjacency
        for successor in adj[task]:
            latest_start[task] = min(
                latest_start[task],
                latest_start[successor] - durations[task]
            )
        # If still infinity (no successors), it's a sink already handled

    # Identify critical tasks: earliest_start == latest_start
    critical_tasks = {
        task for task in all_tasks
        if abs(earliest_start[task] - latest_start[task]) < 1e-9
    }

    # Find a critical source (critical task with no critical predecessors)
    # Build critical adjacency
    critical_adj = {task: [] for task in critical_tasks}
    for a, b in deps:
        if a in critical_tasks and b in critical_tasks:
            critical_adj[a].append(b)

    # Find critical sources (no incoming critical edges)
    critical_sources = set(critical_tasks)
    for a, b in deps:
        if b in critical_tasks and a in critical_tasks:
            critical_sources.discard(b)

    # Start from a critical source and follow critical path
    if not critical_sources:
        # Should not happen if there's at least one critical task
        # But handle edge case
        return (project_duration, [])

    # Reconstruct one critical path
    path = []
    current = next(iter(critical_sources))  # take any critical source

    while current in critical_tasks:
        path.append(current)
        # Find a critical successor
        next_task = None
        for succ in critical_adj[current]:
            if succ in critical_tasks:
                next_task = succ
                break
        if next_task is None:
            break
        current = next_task

    return (project_duration, path)
